// Content repurposing engine (Forgotten Features §2 — wave rebuild).
//
// Ported from the rescued artifacts/api-server/src/routes/content-
// repurposing.ts + src/lib/content-repurposing.ts + lib/outbound-claim-
// guard.ts + lib/x-post-text.ts. The Worker (phase4/_worker.js) owns the
// D1 project/draft/publication rows and emits outbox items; this module is
// the PB side the websync appliers call:
//
//   generateRepurposeDrafts(item, deps) — generate one draft per requested
//     format via the brain (lib/llm.js askLLM) under the original system
//     prompt + outbound-claim guard, charge REPURPOSE_CREDIT_COST against
//     the existing credit_ledger (reserve → settle/refund, idempotency-
//     keyed by the outbox item id — the original's separate reservations
//     table is NOT resurrected), then push the drafts back to the Worker
//     through the HMAC ingest route (deps.poster, provided by websync).
//   publishRepurposeDraft(item, deps) — perform the send for a queued
//     publication (Telegram via the Bot API; X owner-only, exactly as the
//     original; Discord via bot token when one is configured) and report
//     the outcome through the HMAC publish-result route.
//
// Failure honesty: a brain failure (e.g. the free-Gemini quota) refunds the
// reservation and reports status 'failed' with the provider error — never
// a fabricated draft. Business failures are reported and return normally
// (the outbox item is acked); only transport failures throw, so the tick
// retries them next cycle.

import { api, fetch } from 'sdk';
import db, { eq, sql, desc } from 'sdk/db';
import { credit_ledger, x_loop_log } from '../schema.js';
import { getConfig, setConfig, flagValueOn } from './config.js';
import { askLLM } from './llm.js';
import { isChatAdmin, isOwnerId } from './groups.js';
import { raidXGet } from './raids.js';
import { X_EMBEDDED_IMAGES_PBX, xPostLearnBlockText } from './posts.js';

export const REPURPOSE_CREDIT_COST = 3;

export const REPURPOSE_FORMATS = ['x_post', 'telegram_post', 'discord_post'];
export const REPURPOSE_FORMAT_LIMITS = { x_post: 220, telegram_post: 4096, discord_post: 4000 };
export const REPURPOSE_FORMAT_LABELS = {
  x_post: 'X post',
  telegram_post: 'Telegram announcement',
  discord_post: 'Discord announcement',
};

// Verbatim from the original routes/content-repurposing.ts.
export const REPURPOSE_SYSTEM_PROMPT = `You are PB, the PoorBoyAI Content Repurposing Engine.
Create useful, direct community copy from the supplied source. Preserve the source's meaning,
write distinctly for the requested channel, and never invent live metrics, prices, guarantees,
or holder-based subscription discounts, upgrades, or access. Return only the requested copy.
Do not mention internal models, quotas, or pricing unless those facts are explicitly present in
the source and the requested copy genuinely needs them.`;

// The original's per-format generation fallback (routes file).
const REPURPOSE_FALLBACK = 'Review the source and share the strongest useful point with your community.';

// ── outbound-claim guard (port of lib/outbound-claim-guard.ts) ──────────────
// Holder verification is XP-only; it must never be presented as a discount
// or access entitlement.
const HOLDER_SRC =
  '(?:\\$?pbai\\s+)?(?:token\\s+)?holders?|holding\\s+\\$?pbai|hold\\s+\\$?pbai|stak(?:e|ing)\\s+\\$?pbai';
const DISCOUNT_RE =
  /(?:\d+(?:\.\d+)?\s*(?:%|percent)\s*off|\bdiscount(?:s|ed)?\b|\bcheaper\b|\breduced\s+(?:price|cost)|\bsave\s+\$?\d)/i;
const ACCESS_RE =
  /(?:\b(?:free|complimentary)\s+(?:subscription|plan|tier|access)\b|\b(?:subscription\s+)?access\b|\btier\s+(?:access|upgrade)\b|\b(?:unlock(?:s|ed|ing)?|grant(?:s|ed|ing)?|get(?:s|ting)?|receive(?:s|d|ing)?|gain(?:s|ed|ing)?|upgrade(?:s|d|ing)?(?:\s+to)?|move(?:s|d)?\s+(?:up\s+)?to)\b.{0,60}\b(?:starter|hustler|grinder|whale|chad|subscription|plan|tier|access)\b|\b(?:starter|hustler|grinder|whale|chad)\s+(?:access|plan|subscription|tier)\b)/i;
const ALLOWED_BOUNDARIES = [
  /Holding \$PBAI never grants a subscription discount, tier upgrade, or subscription access\./gi,
  /Holder verification is XP-only and never changes subscription access\./gi,
  /Holding \$PBAI never grants or upgrades subscription access\./gi,
  /token holding never grants subscription access/gi,
];
const NEGATIVE_BOUNDARY = new RegExp(
  `(?:\\b(?:no|not)\\b.{0,50})?(?:${HOLDER_SRC}).{0,40}\\b(?:never|does\\s+not|doesn't|do\\s+not|don't|cannot|can't|no\\s+longer)\\b.{0,100}(?:discount|cheaper|subscription|plan|tier|upgrade|access)[^.!?\\n]*`,
  'gi'
);
const REVERSE_NEGATIVE_BOUNDARY =
  /\b(?:no|not)\b.{0,100}(?:discount|cheaper|subscription|plan|tier|upgrade|access).{0,100}(?:(?:\$?pbai\s+)?(?:token\s+)?holders?|holding\s+\$?pbai)/gi;

export function isRetiredHolderAccessClaim(content) {
  let claimText = String(content ?? '');
  for (const allowed of ALLOWED_BOUNDARIES) claimText = claimText.replace(allowed, '');
  for (const sentence of claimText.split(/[.!?\n]+/)) {
    if (!new RegExp(HOLDER_SRC, 'i').test(sentence)) continue;
    const contrast = sentence.match(/\b(?:but|however|yet)\b/i);
    if (!contrast) continue;
    const tail = sentence.slice((contrast.index ?? 0) + contrast[0].length);
    if (DISCOUNT_RE.test(tail) || ACCESS_RE.test(tail)) return true;
  }
  claimText = claimText
    .replace(NEGATIVE_BOUNDARY, 'holders')
    .replace(REVERSE_NEGATIVE_BOUNDARY, 'holders');
  const holderRe = new RegExp(HOLDER_SRC, 'gi');
  for (const match of claimText.matchAll(holderRe)) {
    const start = Math.max(0, (match.index ?? 0) - 140);
    const end = Math.min(claimText.length, (match.index ?? 0) + match[0].length + 140);
    const win = claimText.slice(start, end);
    if (DISCOUNT_RE.test(win) || ACCESS_RE.test(win)) return true;
  }
  return false;
}

export function assertSafeOutboundContent(content) {
  if (isRetiredHolderAccessClaim(content)) {
    throw new Error(
      'Blocked retired holder subscription access, tier, upgrade, free-plan, or discount claim in outbound content.'
    );
  }
}

/**
 * The original's generateSafeOutboundContent: one bounded retry, then the
 * caller-owned safe fallback wholesale (never an edited price/amount).
 */
export async function generateSafeOutboundContent(generate, fallback) {
  for (let attempt = 0; attempt < 2; attempt++) {
    const content = await generate();
    if (content && !isRetiredHolderAccessClaim(content)) return content;
  }
  assertSafeOutboundContent(fallback);
  return fallback;
}

// Simplified port of shortenXPost (lib/x-post-text.ts): whole paragraphs
// under the 220-char X-safe limit; code-point length approximates the
// original's twitter-text weighted length.
export function shortenXPost(text, limit = REPURPOSE_FORMAT_LIMITS.x_post) {
  const normalized = String(text ?? '').replace(/\r\n?/g, '\n').trim();
  if (Array.from(normalized).length <= limit) return normalized;
  const paragraphs = normalized.split(/\n{2,}/).map((p) => p.trim()).filter(Boolean);
  const selected = [];
  for (const p of paragraphs) {
    const candidate = [...selected, p].join('\n\n');
    if (Array.from(candidate).length > limit) break;
    selected.push(p);
  }
  if (selected.length) return selected.join('\n\n');
  const chars = Array.from(normalized);
  return chars.slice(0, Math.max(0, limit - 1)).join('').trimEnd() + '…';
}

function cleanText(value, max) {
  return typeof value === 'string' ? value.trim().slice(0, max) : '';
}

// Verbatim shape from the original generationPrompt().
export function generationPrompt(format, source, instructions) {
  const limit = REPURPOSE_FORMAT_LIMITS[format];
  const channel = REPURPOSE_FORMAT_LABELS[format];
  return [
    `Repurpose the source below into one distinct ${channel}.`,
    `Return only the final copy, no labels or quotation marks. Stay under ${limit} characters.`,
    'Keep the meaning but do not copy the source verbatim. Do not invent prices, live metrics, guarantees, or holder subscription discounts/access.',
    instructions ? `Additional direction: ${instructions}` : '',
    `Source:\n${source}`,
  ].filter(Boolean).join('\n\n');
}

// ── credit ledger (reserve / settle / refund) ───────────────────────────────
// One ledger, the Phase 4 §4.3 credit_ledger. Rows are append-only; each
// step is keyed by refId so a replayed outbox item can never double-charge:
//   reserve: amount -COST, kind 'repurpose_reserve', refId '<base>:reserve'
//   settle:  amount 0,     kind 'repurpose_settle',  refId '<base>:settle'
//   refund:  amount +COST, kind 'repurpose_refund',  refId '<base>:refund'
// Balance is SUM(amount) for userKey 'telegram:<id>' (the same key the
// credit_grant applier writes).

function userKeyFor(tgId) {
  return 'telegram:' + String(tgId);
}

async function ledgerRowByRef(refId) {
  try {
    return await db.select().from(credit_ledger).where(eq(credit_ledger.refId, refId)).get();
  } catch {
    return null;
  }
}

export async function repurposeCreditBalance(tgId) {
  const row = await db.get(sql`SELECT COALESCE(SUM(amount), 0) AS bal FROM credit_ledger WHERE user_key = ${userKeyFor(tgId)}`);
  return Number(row?.bal ?? 0) || 0;
}

/**
 * Reserve REPURPOSE_CREDIT_COST for one generation. `replay` is true when
 * the reserve row already exists (same outbox item re-applied). Throws an
 * 'Insufficient…' error when the balance cannot cover the cost.
 */
export async function reserveRepurposeCredits(tgId, refBase) {
  const refId = refBase + ':reserve';
  const existing = await ledgerRowByRef(refId);
  if (existing) return { replay: true };
  const balance = await repurposeCreditBalance(tgId);
  if (balance < REPURPOSE_CREDIT_COST) {
    throw new Error(
      `Insufficient shared Studio credits. This generation requires ${REPURPOSE_CREDIT_COST} credits.`
    );
  }
  await db.insert(credit_ledger).values({
    userKey: userKeyFor(tgId),
    amount: -REPURPOSE_CREDIT_COST,
    kind: 'repurpose_reserve',
    purpose: 'content_repurposing',
    refId,
  }).run();
  return { replay: false };
}

/** Settle on success (marker row) or refund on failure (+COST back). */
export async function settleRepurposeCredits(tgId, refBase, success) {
  if (success) {
    const refId = refBase + ':settle';
    if (await ledgerRowByRef(refId)) return;
    if (await ledgerRowByRef(refBase + ':refund')) return; // already refunded
    await db.insert(credit_ledger).values({
      userKey: userKeyFor(tgId),
      amount: 0,
      kind: 'repurpose_settle',
      purpose: 'content_repurposing',
      refId,
    }).run();
    return;
  }
  const refundRef = refBase + ':refund';
  if (await ledgerRowByRef(refundRef)) return;
  if (!(await ledgerRowByRef(refBase + ':reserve'))) return; // never charged
  if (await ledgerRowByRef(refBase + ':settle')) return; // already settled
  await db.insert(credit_ledger).values({
    userKey: userKeyFor(tgId),
    amount: REPURPOSE_CREDIT_COST,
    kind: 'repurpose_refund',
    purpose: 'content_repurposing',
    refId: refundRef,
  }).run();
}

// ── generation (repurpose_request applier core) ─────────────────────────────

function itemField(item, key) {
  const v = item?.[key];
  if (v != null) return v;
  return item?.payload?.[key] ?? null;
}

/**
 * Apply one repurpose_request outbox item.
 * deps.poster(path, body) — websync's HMAC signedPost (throws/{error} on
 *   transport failure; a throw here propagates so the tick retries).
 * deps.ask(opts) — defaults to the brain's askLLM; injectable for tests.
 * Returns an outcome object; business failures are reported to the Worker
 * via ingest and returned (acked), never thrown.
 */
export async function generateRepurposeDrafts(item, deps = {}) {
  const ask = deps.ask || askLLM;
  const poster = deps.poster;
  if (typeof poster !== 'function') throw new Error('repurpose: poster dep required');
  const projectId = Number(itemField(item, 'project_id'));
  const clerkUserId = String(itemField(item, 'clerk_user_id') ?? '');
  const tgId = String(itemField(item, 'telegram_user_id') ?? '').trim();
  const formats = (Array.isArray(itemField(item, 'formats')) ? itemField(item, 'formats') : [])
    .filter((f) => REPURPOSE_FORMATS.includes(f));
  const source = String(itemField(item, 'source_content') ?? '');
  const instructions = String(itemField(item, 'instructions') ?? '');
  if (!Number.isInteger(projectId) || !clerkUserId || !tgId || !formats.length) {
    throw new Error('repurpose_request malformed');
  }
  const refBase = 'repurpose:' + String(item.id);

  const reportFailure = async (message) => {
    const res = await poster('/api/internal/repurpose/ingest', {
      project_id: projectId,
      clerk_user_id: clerkUserId,
      status: 'failed',
      error: String(message ?? 'Generation failed.').slice(0, 500),
    });
    if (res && res.error) throw new Error('repurpose ingest report failed: ' + res.error);
    return { ok: false, projectId, error: String(message ?? 'Generation failed.') };
  };

  // Reserve first (original order: reserve → generate → settle/refund).
  try {
    await reserveRepurposeCredits(tgId, refBase);
  } catch (err) {
    // Insufficient credits is a business outcome: report + ack, no charge.
    return await reportFailure(err?.message ?? 'Insufficient credits.');
  }

  let drafts;
  try {
    drafts = [];
    for (const format of formats) {
      const content = await generateSafeOutboundContent(
        () => ask({
          systemPrompt: REPURPOSE_SYSTEM_PROMPT,
          userMessage: generationPrompt(format, source, instructions),
          history: [],
          maxOutputTokens: format === 'x_post' ? 300 : 900,
        }),
        REPURPOSE_FALLBACK
      );
      drafts.push({
        format,
        title: REPURPOSE_FORMAT_LABELS[format],
        content: format === 'x_post'
          ? shortenXPost(content)
          : cleanText(content, REPURPOSE_FORMAT_LIMITS[format]),
      });
    }
  } catch (err) {
    // Brain failure (quota, provider down): refund and report honestly —
    // the project records a retryable failure, never a fabricated draft.
    await settleRepurposeCredits(tgId, refBase, false).catch(() => {});
    return await reportFailure(err?.message ?? 'Generation failed.');
  }

  await settleRepurposeCredits(tgId, refBase, true);
  const res = await poster('/api/internal/repurpose/ingest', {
    project_id: projectId,
    clerk_user_id: clerkUserId,
    status: 'succeeded',
    credit_cost: REPURPOSE_CREDIT_COST,
    drafts,
  });
  if (res && res.error) throw new Error('repurpose ingest failed: ' + res.error);
  return { ok: true, projectId, drafts: drafts.length, charged: REPURPOSE_CREDIT_COST };
}

// ── publishing (repurpose_publish applier core) ─────────────────────────────

async function sendTelegramDraft(tgId, targetId, content) {
  const chatId = String(targetId ?? '').trim();
  if (!chatId) throw new Error('Choose one of your connected Telegram groups first.');
  // The draft may only enter a group the publisher admins (sealing rule:
  // a draft enters a group only when its owner publishes it there).
  if (!(await isChatAdmin(chatId, tgId))) {
    throw new Error('You must be an admin of the target Telegram group to publish there.');
  }
  const sent = await api.sendMessage({ chat_id: chatId, text: content });
  return { externalId: sent?.message_id != null ? String(sent.message_id) : null, externalUrl: null };
}

async function sendDiscordDraft(targetId, content) {
  const channelId = String(targetId ?? '').trim();
  if (!channelId) throw new Error('Connect a Discord channel first.');
  const token = String(await getConfig('DISCORD_BOT_TOKEN', '') || '').trim();
  if (!token) {
    // No Discord credential exists in PB's tgcloud config today (the
    // Discord host owns that bot) — fail honestly instead of pretending.
    throw new Error('Discord publishing is not configured in PB yet (no Discord bot token) — the draft is saved and can be copied manually.');
  }
  const res = await fetch(`https://discord.com/api/v10/channels/${encodeURIComponent(channelId)}/messages`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Authorization: `Bot ${token}` },
    body: JSON.stringify({ content: String(content).slice(0, 2000) }),
  });
  if (!res.ok) throw new Error('Discord rejected this post (HTTP ' + res.status + ').');
  const data = await res.json().catch(() => null);
  return { externalId: data?.id ? String(data.id) : null, externalUrl: null };
}

// ── X publishing (owner-only) ───────────────────────────────────────────────
// Credential resolution: the live set in PB's config is the TWITTER_*
// family — the same keys that power PB's X reads (lib/groups.js,
// lib/digest.js; Rowdy's use-them directive). The original port read the
// X_* names, which hold NO rows in config, so posting always stopped at
// "not configured". Verified live 2026-10-22 (signed GET /2/users/me):
// the authenticating OAuth 1.0a access pair is TWITTER_ACCESS_TOKEN_V1 +
// TWITTER_ACCESS_TOKEN_SECRET — the value under TWITTER_ACCESS_TOKEN is
// an OAuth2-shaped token and 401s for OAuth 1.0a, so the _V1/_SECRET
// names resolve FIRST and the plainer names remain per-field fallbacks.
// Values are never logged or returned. (Rotation note: replace the
// _V1/_TOKEN_SECRET rows — they win while present.)

const X_CRED_NAMES = {
  apiKey: ['TWITTER_API_KEY', 'X_API_KEY'],
  apiSecret: ['TWITTER_API_SECRET', 'X_API_SECRET'],
  accessToken: ['TWITTER_ACCESS_TOKEN_V1', 'TWITTER_ACCESS_TOKEN', 'X_ACCESS_TOKEN'],
  accessSecret: ['TWITTER_ACCESS_TOKEN_SECRET', 'TWITTER_ACCESS_SECRET', 'X_ACCESS_SECRET'],
};

async function resolveXPublisherCreds(getCfg = getConfig) {
  const pick = async (names) => {
    for (const n of names) {
      const v = String((await getCfg(n, '')) || '').trim();
      if (v) return v;
    }
    return '';
  };
  const creds = {};
  for (const [field, names] of Object.entries(X_CRED_NAMES)) creds[field] = await pick(names);
  if (!creds.apiKey || !creds.apiSecret || !creds.accessToken || !creds.accessSecret) return null;
  return creds;
}

let xFetchOverride = null;
export function __setXFetchForTest(fn) { xFetchOverride = fn; }

const xEnc = (s) => encodeURIComponent(s).replace(/[!*'()]/g, (c) => '%' + c.charCodeAt(0).toString(16).toUpperCase());

// Small base64 encoder (binary-string input) — the isolate does not
// guarantee a btoa global (the lesson lib/digest.js's b64ascii already
// records). The inherited signer called btoa and would have thrown in
// production even with correct credentials; this removes that landmine.
function b64bin(str) {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  let out = '';
  for (let i = 0; i < str.length; i += 3) {
    const a = str.charCodeAt(i) & 0xff;
    const b = i + 1 < str.length ? str.charCodeAt(i + 1) & 0xff : 0;
    const c = i + 2 < str.length ? str.charCodeAt(i + 2) & 0xff : 0;
    out += chars[a >> 2] + chars[((a & 3) << 4) | (b >> 4)];
    out += i + 1 < str.length ? chars[((b & 15) << 2) | (c >> 6)] : '=';
    out += i + 2 < str.length ? chars[c & 63] : '=';
  }
  return out;
}

/** OAuth 1.0a HMAC-SHA1 Authorization header for one request (WebCrypto
 *  only; same construction lib/accounts.js's xUsersMe uses). The JSON
 *  body of POST /2/tweets is not part of the signature, per OAuth 1.0a.
 *  extraParams joins the signature base string for form-encoded POSTs
 *  and query-string GETs (RFC 5849: form/query params ARE signed) —
 *  the media upload calls pass their command/media params this way. */
async function xOAuthHeader(method, url, creds, extraParams = {}) {
  const nonce = Array.from({ length: 32 }, () => 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'[Math.floor(Math.random() * 62)]).join('');
  const params = {
    ...extraParams,
    oauth_consumer_key: creds.apiKey,
    oauth_nonce: nonce,
    oauth_signature_method: 'HMAC-SHA1',
    oauth_timestamp: String(Math.floor(Date.now() / 1000)),
    oauth_token: creds.accessToken,
    oauth_version: '1.0',
  };
  const paramString = Object.keys(params).sort().map((k) => `${xEnc(k)}=${xEnc(params[k])}`).join('&');
  const baseString = [method, xEnc(url), xEnc(paramString)].join('&');
  const signingKey = `${xEnc(creds.apiSecret)}&${xEnc(creds.accessSecret)}`;
  const key = await crypto.subtle.importKey('raw', new TextEncoder().encode(signingKey), { name: 'HMAC', hash: 'SHA-1' }, false, ['sign']);
  const sigBuf = await crypto.subtle.sign('HMAC', key, new TextEncoder().encode(baseString));
  const signature = b64bin(String.fromCharCode(...new Uint8Array(sigBuf)));
  return 'OAuth ' + Object.entries({ ...params, oauth_signature: signature })
    .sort(([a], [b]) => (a < b ? -1 : 1))
    .map(([k, v]) => `${xEnc(k)}="${xEnc(v)}"`).join(', ');
}

async function sendXDraft(tgId, content, deps = {}) {
  // Owner-only, exactly as the original enforced (403 there; here the
  // publication is marked failed with the same message — the Worker gate
  // already refused non-owners before queueing).
  if (!(await isOwnerId(tgId))) {
    throw new Error('X publishing is restricted to the official PoorBoyAI publisher.');
  }
  const creds = await resolveXPublisherCreds(deps.getConfig || getConfig);
  if (!creds) {
    // No complete credential set under either name family — fail honestly
    // rather than fabricating a post; the draft stays saved for manual use.
    throw new Error('X publishing is owner-only and no X credentials are configured in PB yet — the draft is saved and can be posted manually.');
  }
  const doFetch = deps.fetch ?? xFetchOverride ?? fetch;
  const url = 'https://api.twitter.com/2/tweets';
  const authHeader = await xOAuthHeader('POST', url, creds);
  const res = await doFetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Authorization: authHeader },
    body: JSON.stringify({ text: shortenXPost(content) }),
  });
  if (!res.ok) throw new Error('X rejected this post (HTTP ' + res.status + ').');
  const data = await res.json().catch(() => null);
  const tweetId = data?.data?.id ? String(data.data.id) : null;
  return { externalId: tweetId, externalUrl: tweetId ? `https://x.com/i/web/status/${tweetId}` : null };
}

/**
 * Read-only credential proof for the X publisher path: resolve the SAME
 * credential set sendXDraft uses and make ONE signed GET /2/users/me.
 * Returns the authenticated identity (id/username/name) or a precise
 * failure (including the HTTP status) — never key material. Performs
 * no posting; used by the operator harness and future health checks.
 */
export async function verifyXPublisherCreds(deps = {}) {
  const creds = await resolveXPublisherCreds(deps.getConfig || getConfig);
  if (!creds) return { ok: false, error: 'no X credentials configured' };
  const doFetch = deps.fetch ?? xFetchOverride ?? fetch;
  const url = 'https://api.twitter.com/2/users/me';
  const authHeader = await xOAuthHeader('GET', url, creds);
  const res = await doFetch(url, { method: 'GET', headers: { Authorization: authHeader } }).catch(() => null);
  if (!res) return { ok: false, error: 'network failure reaching X' };
  if (!res.ok) {
    const detail = await res.text().catch(() => '');
    return { ok: false, httpStatus: res.status, error: ('X users/me HTTP ' + res.status + (detail ? ': ' + detail.slice(0, 200) : '')).trim() };
  }
  const data = await res.json().catch(() => null);
  return { ok: true, id: data?.data?.id ?? null, username: data?.data?.username ?? null, name: data?.data?.name ?? null };
}

/**
 * Apply one repurpose_publish outbox item: run the outbound-claim guard,
 * perform the channel send, and report the outcome to the Worker.
 * Business failures are reported + returned (acked); a failed report
 * throws so the tick retries (the Worker converges replays: only a
 * still-queued publication can transition).
 */
export async function publishRepurposeDraft(item, deps = {}) {
  const poster = deps.poster;
  if (typeof poster !== 'function') throw new Error('repurpose: poster dep required');
  const publicationId = Number(itemField(item, 'publication_id'));
  const tgId = String(itemField(item, 'telegram_user_id') ?? '').trim();
  const channel = String(itemField(item, 'channel') ?? '');
  const targetId = itemField(item, 'target_id');
  const content = String(itemField(item, 'content') ?? '');
  if (!Number.isInteger(publicationId) || !['telegram', 'discord', 'x'].includes(channel) || !content) {
    throw new Error('repurpose_publish malformed');
  }

  let result;
  try {
    assertSafeOutboundContent(content);
    if (channel === 'telegram') result = await sendTelegramDraft(tgId, targetId, content);
    else if (channel === 'discord') result = await sendDiscordDraft(targetId, content);
    else result = await sendXDraft(tgId, content, deps);
  } catch (err) {
    result = { failed: true, error: String(err?.message ?? err ?? 'Publishing failed.').slice(0, 500) };
  }

  const body = result.failed
    ? { publication_id: publicationId, status: 'failed', error: result.error }
    : {
        publication_id: publicationId,
        status: 'succeeded',
        external_id: result.externalId ?? null,
        external_url: result.externalUrl ?? null,
      };
  const res = await poster('/api/internal/repurpose/publish-result', body);
  if (res && res.error) {
    // already_final is convergence, not a failure (a replayed report).
    if (res.error === 'already_final' || res.httpStatus === 409) {
      return { ok: true, publicationId, converged: true };
    }
    throw new Error('repurpose publish-result failed: ' + res.error);
  }
  return { ok: !result.failed, publicationId, ...(result.failed ? { error: result.error } : { externalId: result.externalId ?? null }) };
}

// ── Guarded autonomous X loop (@Poorboyai) ────────────────────────────────
// Approved by Rowdy 2026-10-23 ~21:22 PDT ("Build the X loop — 280 max,
// no threads, 3–4 a day hard cap"). His ban-avoidance law is encoded
// exactly, in the send choke point (xLoopTrySend) so no caller can
// widen it:
//   · SINGLE posts only, ≤280 chars. Over-length is DROPPED + logged —
//     never truncated, never split, never threaded. This path NEVER
//     calls shortenXPost (the repurpose publisher's truncator).
//   · SPLIT daily budgets (Rowdy 2026-11-05 ~18:02, supersedes the shared
//     10/day): marketing POSTS 15/day, REPLIES their own 10/day.
//     Config xloop_daily_cap is the posts cap, clamped to [1,15];
//     xloop_daily_reply_cap is the replies cap, clamped to [1,10].
//     The counters live in config (xloop_budget for posts — the pre-split
//     key, same {day,count} shape; xloop_budget_replies for replies),
//     keyed by the America/Los_Angeles calendar day, so they survive
//     restarts and isolate recycling; they reset at LA midnight by
//     construction. Per-post reply cap (Rowdy 2026-11-05 ~18:04): max 2
//     replies to the SAME post per day (xloop_reply_per_post, day-scoped).
//   · Kill switch: config flag x_loop_off (canonical boolean —
//     /setkey X_LOOP_OFF 1, or /xqueue off). Checked at the cycle head
//     AND inside the choke point; when on, nothing sends.
//   · At most ONE send per tick across all sources. A failed send gets
//     exactly ONE retry inside the same attempt, then the item waits
//     for a later tick — no retry storms. A 429 arms the shared X
//     backoff (raidtrack_backoff_until, the raid cycles' key).
// Sources, in priority order: (A) the owner queue (/xqueue, FIFO),
// (B) milestone cross-posts enqueued by lib/tick.js from the events
// that already make Telegram celebration cards (graduation, ATH,
// price milestones, whale buys), (C) mention replies — direct
// @Poorboyai mentions only, composed by the chat ladder in PB's voice,
// max 1 reply per account per day, never cold outreach.
// Every send / drop / skip lands in x_loop_log.

export const XLOOP_MAX_CHARS = 1000;
export const XLOOP_POSTS_DEFAULT_CAP = 15;
export const XLOOP_POSTS_HARD_CAP = 15;
export const XLOOP_REPLIES_DEFAULT_CAP = 10;
export const XLOOP_REPLIES_HARD_CAP = 10;
export const XLOOP_REPLIES_PER_POST_MAX = 2;
const XLOOP_QUEUE_MAX = 20;
const XLOOP_QUEUE_ITEM_MAX = 1000; // storage bound, now equal to the law by design (see D2 in the 280-lift plan)
const XLOOP_MILESTONE_MAX = 5;
const XLOOP_PURCHASE_MAX = 20;
const XLOOP_MILESTONE_TTL_MS = 48 * 3600_000;
const XLOOP_KEY_RING_MAX = 60;
const XLOOP_MENTION_POLL_MS = 15 * 60_000;
const XLOOP_BACKOFF_MS = 30 * 60_000;
const XLOOP_MILESTONE_PRIORITY = { graduation: 0, ath: 1, milestone: 2, bigbuy: 3, purchase: 4 };

// ── X post pacing (2026-10-28; mention replies gated 2026-10-30 audit #9):
// scheduled sends (queue + milestones) are spread through the day instead
// of bunching at the LA-midnight budget reset. Window is LA wall-clock
// hours [START, END); gap is the minimum time since the last scheduled
// send. Purchases (extra-budget, event-driven) never wait and never stamp
// the clock. Mention replies (reactive) wait on the same window + gap as
// scheduled sends but never stamp the clock; only a successful
// queue/milestone send stamps it.
const XLOOP_PACING_WINDOW_START = 8; // LA hour, inclusive
const XLOOP_PACING_WINDOW_END = 22; // LA hour, exclusive
const XLOOP_PACING_MIN_GAP_MS = 2 * 3600_000;

const XLOOP_REPLY_SYSTEM = [
  'You are PB, the PoorBoyAI community assistant, replying to a mention on X.',
  'Write ONE short, helpful, friendly reply in PB\'s voice. Hard limit: 240 characters.',
  'Plain text only — no markdown, no links, no hashtag spam (one hashtag at most, only if natural).',
  'Never invent prices, metrics, partnerships, guarantees, or features. If you do not know,',
  'say so briefly and point them to the PoorBoyAI community on Telegram.',
].join(' ');

const xLoopLaFmt = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'America/Los_Angeles', year: 'numeric', month: '2-digit', day: '2-digit',
});
export function xLoopDayKey(nowMs = Date.now()) {
  return xLoopLaFmt.format(new Date(nowMs));
}

const xLoopLaHourFmt = new Intl.DateTimeFormat('en-US', {
  timeZone: 'America/Los_Angeles', hour: 'numeric', hour12: false,
});
export function xLoopLaHour(nowMs = Date.now()) {
  const h = Number(xLoopLaHourFmt.format(new Date(nowMs)));
  return h === 24 ? 0 : h; // hour12:false yields "24" at midnight
}

/**
 * Pacing gate for scheduled sends. Returns { allowed: true } or
 * { allowed: false, reason } where reason is 'pacing_night' (outside the
 * LA window) or 'pacing_gap' (last scheduled send too recent). A missing
 * or corrupt xloop_pacing value reads as "no prior send" (open), never as
 * a block. A future lastSentAt blocks fail-closed until the clock passes
 * lastSentAt + gap. Never throws: a pacing decision must never break the
 * tick — worst case it skips a scheduled send for one tick.
 */
export async function xLoopPacingCheck(nowMs = Date.now()) {
  const hour = xLoopLaHour(nowMs);
  if (hour < XLOOP_PACING_WINDOW_START || hour >= XLOOP_PACING_WINDOW_END) {
    return { allowed: false, reason: 'pacing_night' };
  }
  const rec = await xLoopReadJson('xloop_pacing', null);
  const last = rec && Number.isFinite(rec.lastSentAt) ? rec.lastSentAt : null;
  if (last != null && nowMs - last < XLOOP_PACING_MIN_GAP_MS) {
    return { allowed: false, reason: 'pacing_gap' };
  }
  return { allowed: true };
}

async function xLoopPacingStamp(nowMs) {
  await setConfig('xloop_pacing', JSON.stringify({ lastSentAt: nowMs })).catch(() => {});
}

const xCharLen = (s) => Array.from(String(s ?? '')).length;
const cmpXId = (a, b) => (a.length !== b.length ? a.length - b.length : (a < b ? -1 : a > b ? 1 : 0));

async function xLoopReadJson(key, fallback) {
  try {
    const raw = await getConfig(key, '');
    const v = raw ? JSON.parse(raw) : null;
    return v ?? fallback;
  } catch { return fallback; }
}

async function xLoopLog(row) {
  await db.insert(x_loop_log).values({
    ts: Math.floor(Date.now() / 1000),
    kind: row.kind,
    status: row.status,
    tweetId: row.tweetId ?? null,
    inReplyTo: row.inReplyTo ?? null,
    authorId: row.authorId ?? null,
    text: row.text ? String(row.text).slice(0, 300) : null,
    detail: row.detail ? String(row.detail).slice(0, 200) : null,
  }).run().catch(() => {});
}

export async function xLoopIsOff() {
  return flagValueOn(await getConfig('x_loop_off', null));
}

/** Outage-X suppression (video-automatic wave 2026-11-06): config flag
 *  x_outage_off. When ON, outage notices never reach the X queue — the
 *  normal lane (video/ads/airdrop/milestones) keeps flowing. The home
 *  (support-group) legs are untouched. OFF/unset = previous behavior. */
export async function xOutageOff() {
  return flagValueOn(await getConfig('x_outage_off', null));
}

/** Today's split budget state (LA calendar day):
 *  { day, postsCap, postsUsed, postsRemaining, repliesCap, repliesUsed,
 *    repliesRemaining }. Posts read the pre-split xloop_budget key
 *  ({day,count} — a stored pre-split row counts as posts-used, fail-closed
 *  for one transition evening); replies read xloop_budget_replies. */
export async function xLoopBudgetState(nowMs = Date.now()) {
  const day = xLoopDayKey(nowMs);
  const postsCapRaw = Number(await getConfig('xloop_daily_cap', ''));
  const postsCap = Number.isFinite(postsCapRaw) && postsCapRaw > 0
    ? Math.min(XLOOP_POSTS_HARD_CAP, Math.max(1, Math.floor(postsCapRaw)))
    : XLOOP_POSTS_DEFAULT_CAP;
  const repliesCapRaw = Number(await getConfig('xloop_daily_reply_cap', ''));
  const repliesCap = Number.isFinite(repliesCapRaw) && repliesCapRaw > 0
    ? Math.min(XLOOP_REPLIES_HARD_CAP, Math.max(1, Math.floor(repliesCapRaw)))
    : XLOOP_REPLIES_DEFAULT_CAP;
  const postsRec = await xLoopReadJson('xloop_budget', null);
  const postsUsed = postsRec && postsRec.day === day && Number.isFinite(postsRec.count) ? Math.max(0, Math.floor(postsRec.count)) : 0;
  const repliesRec = await xLoopReadJson('xloop_budget_replies', null);
  const repliesUsed = repliesRec && repliesRec.day === day && Number.isFinite(repliesRec.count) ? Math.max(0, Math.floor(repliesRec.count)) : 0;
  return {
    day,
    postsCap, postsUsed, postsRemaining: Math.max(0, postsCap - postsUsed),
    repliesCap, repliesUsed, repliesRemaining: Math.max(0, repliesCap - repliesUsed),
  };
}

async function xLoopSpendBudget(day, lane = 'posts') {
  const key = lane === 'replies' ? 'xloop_budget_replies' : 'xloop_budget';
  const rec = await xLoopReadJson(key, null);
  const count = rec && rec.day === day && Number.isFinite(rec.count) ? Math.floor(rec.count) + 1 : 1;
  await setConfig(key, JSON.stringify({ day, count })).catch(() => {});
  return count;
}

/** Replies already sent today to one post (xloop_reply_per_post, day-scoped). */
async function xLoopReplyPerPostCount(day, tweetId) {
  const rec = await xLoopReadJson('xloop_reply_per_post', null);
  if (!rec || rec.day !== day || !rec.counts || typeof rec.counts !== 'object') return 0;
  const n = Number(rec.counts[String(tweetId)]);
  return Number.isFinite(n) ? Math.max(0, Math.floor(n)) : 0;
}

async function xLoopSpendReplyPerPost(day, tweetId) {
  const rec = await xLoopReadJson('xloop_reply_per_post', null);
  const counts = rec && rec.day === day && rec.counts && typeof rec.counts === 'object' ? { ...rec.counts } : {};
  const id = String(tweetId);
  counts[id] = (Number.isFinite(Number(counts[id])) ? Math.floor(Number(counts[id])) : 0) + 1;
  await setConfig('xloop_reply_per_post', JSON.stringify({ day, counts })).catch(() => {});
  return counts[id];
}

async function xLoopArmBackoff() {
  await setConfig('raidtrack_backoff_until', String(Date.now() + XLOOP_BACKOFF_MS)).catch(() => {});
}

/**
 * Verbatim X post through the SAME signer/credential path as
 * sendXDraft — but NO shortenXPost: the text goes out exactly as
 * given (callers enforce the 280 law before calling). Returns the
 * tweet id (null when X answered 200 without one); throws on HTTP
 * failure with err.status attached.
 */
async function postXVerbatim(text, replyTo = null, deps = {}, mediaIds = null) {
  const creds = await resolveXPublisherCreds(deps.getConfig || getConfig);
  if (!creds) throw new Error('xloop: no X credentials configured');
  const doFetch = deps.fetch ?? xFetchOverride ?? fetch;
  const url = 'https://api.twitter.com/2/tweets';
  const authHeader = await xOAuthHeader('POST', url, creds);
  const payload = replyTo
    ? { text, reply: { in_reply_to_tweet_id: String(replyTo) } }
    : { text };
  if (Array.isArray(mediaIds) && mediaIds.length) payload.media = { media_ids: mediaIds.map(String) };
  const res = await doFetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Authorization: authHeader },
    body: JSON.stringify(payload),
  });
  if (!res.ok) {
    const err = new Error('X post rejected (HTTP ' + res.status + ')');
    err.status = res.status;
    throw err;
  }
  const data = await res.json().catch(() => null);
  return data?.data?.id ? String(data.data.id) : null;
}

// ── X media upload (chunked v1.1, media upload wave 2026-10-25) ─────────────
// upload.twitter.com/1.1/media/upload.json, INIT → APPEND → FINALIZE.
// INIT and FINALIZE are URL-encoded form posts (all params signed).
// APPEND is multipart/form-data with a BINARY media part (multipart
// wave 2026-10-26): the isolate fetch path rejects URL-encoded APPEND
// bodies at ~22KB and up (431 / transport failure, size-ordered, while
// tiny bodies pass — diagnosed 2026-10-26), but multipart binary bodies
// pass at full size (real thank-you image proven INIT 202 → APPEND 204
// → FINALIZE 201 in-isolate). Per RFC 5849, multipart body parameters
// are EXCLUDED from the signature base string — APPEND signs oauth_*
// only (verified live: X accepts this; the urlencoded shape signed all
// params including media_data). Queue items carry an imageKey, never
// the bytes, so the config queue stays tiny; the bytes live in
// X_EMBEDDED_IMAGES below (code, not config — the bot runs serverless
// and cannot read VM files). FAIL-SAFE: upload + FINALIZE must succeed
// BEFORE any tweet-create call; on upload failure no tweet is created
// and the item is struck exactly like any other failed send.

const X_MEDIA_UPLOAD_URL = 'https://upload.twitter.com/1.1/media/upload.json';
// One APPEND chunk of raw bytes. The thank-you image (188,790 bytes)
// uploads in a single chunk.
const X_MEDIA_CHUNK_BYTES = 1048575;

const xFormBody = (params) => Object.entries(params)
  .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(String(v))}`).join('&');

async function xMediaPost(params, creds, deps) {
  const doFetch = deps.fetch ?? xFetchOverride ?? fetch;
  const authHeader = await xOAuthHeader('POST', X_MEDIA_UPLOAD_URL, creds, params);
  const res = await doFetch(X_MEDIA_UPLOAD_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded', Authorization: authHeader },
    body: xFormBody(params),
  });
  if (!res.ok) {
    const err = new Error('X media upload rejected (HTTP ' + res.status + ')');
    err.status = res.status;
    throw err;
  }
  return res.json().catch(() => null);
}

// base64 -> bytes (the isolate has no atob global). Shifts verified
// against the registry image bytes (SHA-256) before shipping.
function b64decode(b64) {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  const rev = {};
  for (let i = 0; i < chars.length; i++) rev[chars[i]] = i;
  const clean = String(b64).replace(/[^A-Za-z0-9+/=]/g, '');
  const pad = clean.endsWith('==') ? 2 : (clean.endsWith('=') ? 1 : 0);
  const len = Math.floor((clean.length * 3) / 4) - pad;
  const out = new Uint8Array(len);
  let o = 0;
  for (let i = 0; i < clean.length; i += 4) {
    const a = rev[clean[i]] ?? 0;
    const b = rev[clean[i + 1]] ?? 0;
    const c = clean[i + 2] === '=' ? 0 : (rev[clean[i + 2]] ?? 0);
    const d = clean[i + 3] === '=' ? 0 : (rev[clean[i + 3]] ?? 0);
    if (o < len) out[o++] = ((a << 2) | (b >> 4)) & 0xff;
    if (o < len) out[o++] = (((b & 15) << 4) | (c >> 2)) & 0xff;
    if (o < len) out[o++] = (((c & 3) << 6) | d) & 0xff;
  }
  return out;
}

function buildMultipartBody(fields, mediaBytes, boundary, fileOpts = {}) {
  const enc = new TextEncoder();
  const parts = [];
  for (const [k, v] of Object.entries(fields)) {
    parts.push(enc.encode(`--${boundary}\r\nContent-Disposition: form-data; name="${k}"\r\n\r\n${v}\r\n`));
  }
  const filename = fileOpts.filename ?? 'media.webp';
  parts.push(enc.encode(`--${boundary}\r\nContent-Disposition: form-data; name="media"; filename="${filename}"\r\nContent-Type: application/octet-stream\r\n\r\n`));
  parts.push(mediaBytes);
  parts.push(enc.encode(`\r\n--${boundary}--\r\n`));
  let total = 0;
  for (const p of parts) total += p.length;
  const out = new Uint8Array(total);
  let o = 0;
  for (const p of parts) { out.set(p, o); o += p.length; }
  return out;
}

// Multipart APPEND: binary media part, oauth_*-only signature (RFC 5849
// excludes multipart body params from the base string).
async function xMediaPostMultipart(mediaId, segment, mediaBytes, creds, deps, fileOpts = {}) {
  const doFetch = deps.fetch ?? xFetchOverride ?? fetch;
  const authHeader = await xOAuthHeader('POST', X_MEDIA_UPLOAD_URL, creds, {});
  const boundary = '----PBFormBoundary' + Date.now().toString(36) + Math.floor(Math.random() * 1e12).toString(36);
  const body = buildMultipartBody(
    { command: 'APPEND', media_id: mediaId, segment_index: String(segment) },
    mediaBytes, boundary, fileOpts,
  );
  const res = await doFetch(X_MEDIA_UPLOAD_URL, {
    method: 'POST',
    headers: { 'Content-Type': `multipart/form-data; boundary=${boundary}`, Authorization: authHeader },
    body,
  });
  if (!res.ok) {
    const err = new Error('X media upload rejected (HTTP ' + res.status + ')');
    err.status = res.status;
    throw err;
  }
  return res.json().catch(() => null);
}

async function xMediaStatus(mediaId, creds, deps) {
  const doFetch = deps.fetch ?? xFetchOverride ?? fetch;
  const params = { command: 'STATUS', media_id: mediaId };
  const authHeader = await xOAuthHeader('GET', X_MEDIA_UPLOAD_URL, creds, params);
  const res = await doFetch(`${X_MEDIA_UPLOAD_URL}?${xFormBody(params)}`, {
    method: 'GET',
    headers: { Authorization: authHeader },
  });
  if (!res.ok) {
    const err = new Error('X media status rejected (HTTP ' + res.status + ')');
    err.status = res.status;
    throw err;
  }
  return res.json().catch(() => null);
}

/** Chunked upload of one base64 image. Returns the media_id string. */
export async function uploadXMedia(mediaB64, mediaType, deps = {}) {
  const creds = await resolveXPublisherCreds(deps.getConfig || getConfig);
  if (!creds) throw new Error('xmedia: no X credentials configured');
  const b64 = String(mediaB64 ?? '');
  if (!b64) throw new Error('xmedia: empty media');
  const bytes = b64decode(b64);
  const totalBytes = bytes.length;
  const init = await xMediaPost(
    { command: 'INIT', total_bytes: String(totalBytes), media_type: mediaType, media_category: 'tweet_image' },
    creds, deps,
  );
  const mediaId = init?.media_id_string ? String(init.media_id_string)
    : (init?.media_id != null ? String(init.media_id) : null);
  if (!mediaId) throw new Error('xmedia: INIT returned no media_id');
  let segment = 0;
  for (let off = 0; off < bytes.length; off += X_MEDIA_CHUNK_BYTES, segment++) {
    await xMediaPostMultipart(mediaId, segment, bytes.slice(off, off + X_MEDIA_CHUNK_BYTES), creds, deps);
  }
  let fin = await xMediaPost({ command: 'FINALIZE', media_id: mediaId }, creds, deps);
  // Images finalize synchronously (no processing_info); if one ever
  // shows up pending, poll STATUS a few times before giving up —
  // never post against unprocessed media.
  for (let poll = 0; poll < 5 && fin?.processing_info?.state === 'pending'; poll++) {
    await new Promise((r) => { try { setTimeout(r, 1000); } catch { r(); } });
    fin = await xMediaStatus(mediaId, creds, deps);
  }
  if (fin?.processing_info?.state === 'failed') {
    throw new Error('xmedia: processing failed: ' + (fin.processing_info.error?.message ?? 'unknown'));
  }
  if (fin?.processing_info?.state === 'pending') throw new Error('xmedia: processing still pending');
  return mediaId;
}

// ── Video upload (video-to-X wave 2026-11-04) ─────────────────────────────
// Brought over from the Replit era and upgraded for the isolate: the
// Replit video path rode the twitter-api-v2 library on a Node server
// (no custom upload code to restore — archive grep, zero hits for
// tweet_video/media_category/uploadMedia/media_ids), and its signing
// contract (OAuth 1.0a HMAC-SHA1 on EVERY v1.1 call incl. STATUS, INIT/
// FINALIZE params in the signature, APPEND multipart excluded) is
// already the shape of xMediaPost/xMediaPostMultipart/xMediaStatus
// above. What the library did that CANNOT port is its internal
// await/poll for STATUS — Node awaits/timers do not exist in the
// isolate, and endpoints die ~33s — so video processing is polled
// across TICKS (Phase A upload → xloop_video_pending → Phase B poll
// in cycleXLoop), never awaited in one call. Video bytes are NEVER
// embedded base64 (the 1MB module cap forbids MP4s in code): they come
// from a Studio render's Telegram file_id, resolved at send time.
export const X_VIDEO_MAX_BYTES = 64 * 1024 * 1024; // X allows 512MB; the isolate does not need that much
export const X_VIDEO_PENDING_TTL_MS = 30 * 60_000; // a video that never finishes processing drops, never blocks
const XLOOP_VIDEO_PENDING_KEY = 'xloop_video_pending';

/** Config key holding a Studio job's Telegram file_id, set by the delivery-time capture wave. */
export function studioVideoFileKey(jobId) { return `studio_video_file:${String(jobId ?? '')}`; }

/** Resolve a Studio job's video bytes via its captured Telegram file_id. No file_id → no bytes, no post. */
export async function resolveStudioVideoBytes(videoJobId, deps = {}) {
  const fileId = await getConfig(studioVideoFileKey(videoJobId)).catch(() => null);
  if (!fileId) return { ok: false, reason: 'no_file' };
  const getFile = deps.getFileContent ?? (api?.getFileContent ? api.getFileContent.bind(api) : null);
  if (!getFile) return { ok: false, reason: 'no_file_api' };
  let bytes;
  try { bytes = await getFile(String(fileId)); } catch (e) { return { ok: false, reason: 'file_fetch_failed', detail: String(e?.message ?? e).slice(0, 120) }; }
  if (!bytes || !bytes.length) return { ok: false, reason: 'empty_file' };
  if (bytes.length > X_VIDEO_MAX_BYTES) return { ok: false, reason: 'too_large' };
  return { ok: true, bytes, fileId: String(fileId) };
}

/** Chunked upload of raw video bytes. Returns the media_id string; the
 * caller polls STATUS on later ticks — video processing is async and
 * the isolate must never await it. A FINALIZE that already reports
 * failed throws immediately (a dead upload never becomes a pending). */
export async function uploadXVideoBytes(bytes, deps = {}) {
  const creds = await resolveXPublisherCreds(deps.getConfig || getConfig);
  if (!creds) throw new Error('xvideo: no X credentials configured');
  const data = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes ?? []);
  if (!data.length) throw new Error('xvideo: empty media');
  if (data.length > X_VIDEO_MAX_BYTES) throw new Error('xvideo: media too large');
  const init = await xMediaPost(
    { command: 'INIT', total_bytes: String(data.length), media_type: 'video/mp4', media_category: 'tweet_video' },
    creds, deps,
  );
  const mediaId = init?.media_id_string ? String(init.media_id_string)
    : (init?.media_id != null ? String(init.media_id) : null);
  if (!mediaId) throw new Error('xvideo: INIT returned no media_id');
  let segment = 0;
  for (let off = 0; off < data.length; off += X_MEDIA_CHUNK_BYTES, segment++) {
    await xMediaPostMultipart(mediaId, segment, data.slice(off, off + X_MEDIA_CHUNK_BYTES), creds, deps, { filename: 'media.mp4' });
  }
  const fin = await xMediaPost({ command: 'FINALIZE', media_id: mediaId }, creds, deps);
  if (fin?.processing_info?.state === 'failed') {
    throw new Error('xvideo: processing failed: ' + (fin.processing_info.error?.message ?? 'unknown'));
  }
  return mediaId;
}

/** INIT-only proof seam (video-to-X wave): runs the real INIT step with
 * the live OAuth 1.0a creds and returns the media_id. Creates NO tweet,
 * queues NOTHING, uploads NO bytes — the media_id is orphaned and
 * expires unposted. Used by the run-only in-isolate proof endpoint. */
export async function xVideoInitProbe(totalBytes, deps = {}) {
  const creds = await resolveXPublisherCreds(deps.getConfig || getConfig);
  if (!creds) throw new Error('xvideo: no X credentials configured');
  const init = await xMediaPost(
    { command: 'INIT', total_bytes: String(Number(totalBytes) || 0), media_type: 'video/mp4', media_category: 'tweet_video' },
    creds, deps,
  );
  const mediaId = init?.media_id_string ? String(init.media_id_string)
    : (init?.media_id != null ? String(init.media_id) : null);
  if (!mediaId) throw new Error('xvideo: INIT returned no media_id');
  return { mediaId, processingInfo: init?.processing_info ?? null };
}

export async function xVideoPendingRead() {
  const p = await xLoopReadJson(XLOOP_VIDEO_PENDING_KEY, null);
  return p && typeof p === 'object' ? p : null;
}

async function xVideoPendingWrite(p) {
  await setConfig(XLOOP_VIDEO_PENDING_KEY, JSON.stringify(p)).catch(() => {});
}

async function xVideoPendingClear() {
  await setConfig(XLOOP_VIDEO_PENDING_KEY, '').catch(() => {});
}

// Embedded image registry: key → { mediaType, b64 }. Only the thank-you
// image ships this wave; later images add a key here, never queue bytes.
export const X_EMBEDDED_IMAGES = {
  // Thank-you image (dark green, no year), webp — X accepts webp for
  // tweet_image. Bytes inserted at build time; placeholder replaced by
  // the wave script, never hand-edited.
  thankyou: { mediaType: 'image/webp', b64: '' },
  // First-purchase image (Ad Creator, 2026-10-27), webp.
  firstpurchase: { mediaType: 'image/webp', b64: '' },
};

export function resolveXImage(key) {
  const k = String(key ?? '');
  const img = X_EMBEDDED_IMAGES[k] ?? X_EMBEDDED_IMAGES_PBX[k];
  return img && typeof img.b64 === 'string' && img.b64.length > 100 ? img : null;
}

/** Registry metadata WITHOUT the bytes (safe for status/logs). */
export function xImageInfo(key) {
  const k = String(key ?? '');
  const img = X_EMBEDDED_IMAGES[k] ?? X_EMBEDDED_IMAGES_PBX[k];
  return img ? { mediaType: img.mediaType, b64Length: img.b64.length } : null;
}

// Approved thank-you text (Rowdy-approved 2026-10-25, 159 chars).
// Posted only via /xqueue thankyou → the guarded loop; never directly.
export const X_THANKYOU_TEXT = 'Thank you to all our new followers — welcome to the PoorBoyAI family. 🙏 More tools are rolling out soon. Stay tuned, this is just the beginning. #PoorBoyAI #PBAI';

/**
 * The send choke point — every loop send passes through here and the
 * law is re-checked at the door (kill switch → length → claim guard →
 * budget), never trusted from the caller. One retry on failure, then
 * the caller decides (queue/milestone strike, reply drop).
 * budgetExempt (purchase announcements only, Rowdy 2026-10-27):
 * skips the shared-budget check AND the spend — killswitch, length,
 * guard, and media checks still apply.
 * mediaIds (video-to-X wave 2026-11-04): a pre-uploaded media_id list
 * (Phase B video post) — used directly, skipping the imageKey upload.
 * Returns { sent:true, tweetId } | { sent:false, reason }.
 */
async function xLoopTrySend({ kind, text, replyTo = null, authorId = null, detail = null, imageKey = null, mediaIds: preMediaIds = null, budgetExempt = false }, deps = {}) {
  const now = deps.nowMs ?? Date.now();
  const clean = String(text ?? '').trim();
  if (await xLoopIsOff()) {
    await xLoopLog({ kind, status: 'skipped_killswitch', text: clean, inReplyTo: replyTo, authorId, detail });
    return { sent: false, reason: 'killswitch' };
  }
  if (!clean || xCharLen(clean) > XLOOP_MAX_CHARS) {
    await xLoopLog({ kind, status: 'dropped_overlength', text: clean, inReplyTo: replyTo, authorId, detail });
    return { sent: false, reason: 'overlength' };
  }
  try {
    assertSafeOutboundContent(clean);
  } catch (e) {
    await xLoopLog({ kind, status: 'dropped_guard', text: clean, inReplyTo: replyTo, authorId, detail: String(e?.message ?? e).slice(0, 120) });
    return { sent: false, reason: 'guard' };
  }
  const budget = await xLoopBudgetState(now);
  const isReply = kind === 'reply';
  // Split budgets (Rowdy 2026-11-05): replies draw the replies lane,
  // everything else draws the posts lane. A reply to a post already
  // answered twice today is refused before any budget is touched.
  // Purchase announcements are EXTRA-budget (Rowdy 2026-10-27): a
  // budgetExempt send skips the lane checks AND the spend.
  if (!budgetExempt) {
    if (isReply && replyTo && (await xLoopReplyPerPostCount(budget.day, replyTo)) >= XLOOP_REPLIES_PER_POST_MAX) {
      await xLoopLog({ kind, status: 'skipped_per_post_cap', text: clean, inReplyTo: replyTo, authorId, detail });
      return { sent: false, reason: 'per_post_cap' };
    }
    const remaining = isReply ? budget.repliesRemaining : budget.postsRemaining;
    if (remaining <= 0) {
      await xLoopLog({ kind, status: 'skipped_budget', text: clean, inReplyTo: replyTo, authorId, detail });
      return { sent: false, reason: 'budget' };
    }
  }
  // Media FIRST (media wave 2026-10-25): upload + FINALIZE must succeed
  // before any tweet-create call, and a successful upload is reused
  // across the create retries below. On upload failure nothing is
  // posted, no budget is spent, and the item is struck like any other
  // failed send. An unknown imageKey is poisoned — drop it like a
  // guard failure, logged.
  let mediaIds = null;
  if (Array.isArray(preMediaIds) && preMediaIds.length) {
    mediaIds = [...preMediaIds]; // Phase B video: media already uploaded + processed
  } else if (imageKey) {
    const img = resolveXImage(imageKey);
    if (!img) {
      await xLoopLog({ kind, status: 'dropped_noimage', text: clean, inReplyTo: replyTo, authorId, detail });
      return { sent: false, reason: 'guard' };
    }
    try {
      mediaIds = [await uploadXMedia(img.b64, img.mediaType, deps)];
    } catch (e) {
      if (e?.status === 429) await xLoopArmBackoff();
      await xLoopLog({ kind, status: 'failed_media', text: clean, inReplyTo: replyTo, authorId, detail: String(e?.message ?? e).slice(0, 120) });
      return { sent: false, reason: 'failed' };
    }
  }
  let tweetId = null;
  let lastErr = null;
  for (let attempt = 0; attempt < 2; attempt++) {
    try {
      tweetId = await postXVerbatim(clean, replyTo, deps, mediaIds);
      lastErr = null;
      break;
    } catch (e) {
      lastErr = e;
      if (e?.status === 429) await xLoopArmBackoff();
    }
  }
  if (lastErr) {
    await xLoopLog({ kind, status: 'failed', text: clean, inReplyTo: replyTo, authorId, detail: String(lastErr?.message ?? lastErr).slice(0, 120) });
    return { sent: false, reason: 'failed' };
  }
  if (!budgetExempt) {
    await xLoopSpendBudget(budget.day, isReply ? 'replies' : 'posts');
    if (isReply && replyTo) await xLoopSpendReplyPerPost(budget.day, replyTo);
  }
  await xLoopLog({ kind, status: 'sent', tweetId, inReplyTo: replyTo, authorId, text: clean, detail });
  return { sent: true, tweetId };
}

// ── (A) Owner queue — config key xloop_queue, FIFO ──────────────────────────

export async function xQueueList() {
  const q = await xLoopReadJson('xloop_queue', []);
  return Array.isArray(q) ? q.filter((i) => i && typeof i.text === 'string') : [];
}

async function xQueueSave(queue) {
  await setConfig('xloop_queue', JSON.stringify(queue.slice(0, XLOOP_QUEUE_MAX))).catch(() => {});
}

export async function xQueueAdd(text, byId = null, imageKey = null, videoJobId = null) {
  const clean = String(text ?? '').trim();
  if (!clean) return { ok: false, reason: 'empty' };
  const queue = await xQueueList();
  if (queue.length >= XLOOP_QUEUE_MAX) return { ok: false, reason: 'queue_full' };
  const item = {
    id: Date.now().toString(36) + Math.floor(Math.random() * 1e4).toString(36),
    text: clean.slice(0, XLOOP_QUEUE_ITEM_MAX),
    at: Date.now(),
    by: byId != null ? String(byId) : null,
    attempts: 0,
  };
  if (imageKey != null) {
    if (!resolveXImage(imageKey)) return { ok: false, reason: 'bad_image' };
    item.imageKey = String(imageKey); // key only — bytes stay in the registry
  }
  if (videoJobId != null) {
    // Video-to-X wave: a video item carries a Studio job id, never
    // bytes — the bytes resolve at send time from its captured
    // Telegram file_id (studio_video_file:<jobId>). A video item and
    // an image item are mutually exclusive.
    if (imageKey != null) return { ok: false, reason: 'video_and_image' };
    item.videoJobId = String(videoJobId);
  }
  queue.push(item);
  await xQueueSave(queue);
  return { ok: true, item, position: queue.length, overLength: xCharLen(item.text) > XLOOP_MAX_CHARS };
}

/** Queue a video ad to X (video-automatic wave 2026-11-06): the single
 *  entry point for video posts. The item carries a Studio job id, never
 *  bytes — the bytes resolve at send time from its captured Telegram
 *  file_id. Queueing is NOT posting: the tick drains it automatically
 *  inside the daily budget, pacing, and kill switch. No tap involved.
 *  Dedup: the same job id queues at most once. */
export async function xQueueAddVideo(text, videoJobId, byId = null) {
  if (videoJobId == null || String(videoJobId).trim() === '') return { ok: false, reason: 'no_video_job' };
  const queue = await xQueueList();
  if (queue.some((i) => i && String(i.videoJobId ?? '') === String(videoJobId))) {
    return { ok: false, reason: 'already_queued' };
  }
  return xQueueAdd(text, byId, null, videoJobId);
}

// ── (A2) Priority queue — outage notices (2026-11-04) ─────────────────────
// A priority item jumps ahead of marketing posts but behind any priority
// items already queued, so priority order stays first-in-first-out. Pure
// insert (no I/O) so the wave's proof can verify ordering on fake queues
// without touching the real xloop_queue.
export function xQueueInsertPriority(queue, item) {
  const out = Array.isArray(queue) ? [...queue] : [];
  let i = 0;
  while (i < out.length && out[i] && out[i].priority) i++;
  out.splice(i, 0, item);
  return out;
}

/** Queue a priority (outage-notice) item: same bounds as xQueueAdd, but
 *  inserted after the leading priority run instead of appended. The send
 *  itself still runs the choke point (kill switch, 1000-char drop, guard,
 *  budget spend, logging) — priority changes position and pacing only,
 *  never the send rules. */
export async function xQueueAddPriority(text, byId = null) {
  const clean = String(text ?? '').trim();
  if (!clean) return { ok: false, reason: 'empty' };
  const queue = await xQueueList();
  if (queue.length >= XLOOP_QUEUE_MAX) return { ok: false, reason: 'queue_full' };
  const item = {
    id: Date.now().toString(36) + Math.floor(Math.random() * 1e4).toString(36),
    text: clean.slice(0, XLOOP_QUEUE_ITEM_MAX),
    at: Date.now(),
    by: byId != null ? String(byId) : null,
    attempts: 0,
    priority: true,
  };
  const next = xQueueInsertPriority(queue, item);
  await xQueueSave(next);
  return { ok: true, item, position: next.indexOf(item) + 1, overLength: xCharLen(item.text) > XLOOP_MAX_CHARS };
}

/** Queue the approved thank-you post + image (media wave 2026-10-25).
 *  Refuses when one is already queued, so a double-tap cannot post it
 *  twice. Queueing is NOT posting: the loop sends it on a coming tick
 *  inside the daily budget, kill switch, and 280 law. */
export async function xQueueAddThankyou(byId = null) {
  const queue = await xQueueList();
  if (queue.some((i) => i && i.imageKey === 'thankyou')) return { ok: false, reason: 'already_queued' };
  return xQueueAdd(X_THANKYOU_TEXT, byId, 'thankyou');
}

export async function xQueueRemove(index1) {
  const queue = await xQueueList();
  const n = Number(index1);
  if (!Number.isInteger(n) || n < 1 || n > queue.length) return { ok: false, reason: 'no_such_item' };
  const [removed] = queue.splice(n - 1, 1);
  await xQueueSave(queue);
  return { ok: true, removed };
}

export async function xQueueClear() {
  const queue = await xQueueList();
  await xQueueSave([]);
  return { ok: true, cleared: queue.length };
}

async function xLoopDrainQueue(deps) {
  let queue = await xQueueList();
  let guard = 0;
  while (queue.length && guard++ < XLOOP_QUEUE_MAX + 2) {
    const head = queue[0];
    // Phase A (video-to-X wave): a video head item uploads FIRST and
    // leaves the queue as a pending record — the tick's send slot is
    // NOT spent, and nothing posts until a later tick's STATUS poll
    // reports succeeded. A video head NEVER reaches xLoopTrySend
    // without a mediaId, so a video can never post text-only.
    if (head.videoJobId) {
      if (await xLoopIsOff()) return { sent: 0, stopped: 'killswitch' };
      const resolved = await resolveStudioVideoBytes(head.videoJobId, deps);
      if (!resolved.ok) {
        await xLoopLog({ kind: 'queue', status: 'dropped_novideo', detail: `queue:${head.id} ${resolved.reason}`, text: head.text });
        queue = queue.slice(1);
        await xQueueSave(queue);
        continue;
      }
      let mediaId;
      try {
        mediaId = await uploadXVideoBytes(resolved.bytes, deps);
      } catch (e) {
        if (e?.status === 429) await xLoopArmBackoff();
        await xLoopLog({ kind: 'queue', status: 'failed_media', text: head.text, detail: `queue:${head.id} ${String(e?.message ?? e).slice(0, 120)}` });
        head.attempts = (head.attempts ?? 0) + 1;
        if (head.attempts >= 3) {
          await xLoopLog({ kind: 'queue', status: 'dropped_failed', detail: `queue:${head.id} attempts:${head.attempts}`, text: head.text });
          queue = queue.slice(1);
        }
        await xQueueSave(queue);
        return { sent: 0, failed: 'queue' };
      }
      await xVideoPendingWrite({ queueId: head.id, mediaId, text: head.text, attempts: 0, firstSeenAt: deps.nowMs ?? Date.now(), processingLogged: false });
      await xLoopLog({ kind: 'queue', status: 'video_uploading', detail: `video:${head.id}`, text: head.text });
      queue = queue.slice(1);
      await xQueueSave(queue);
      return { sent: 0, videoUploaded: true };
    }
    const r = await xLoopTrySend({ kind: 'queue', text: head.text, imageKey: head.imageKey ?? null, detail: `queue:${head.id}` }, deps);
    if (r.sent) {
      queue = queue.slice(1);
      await xQueueSave(queue);
      return { sent: 1, kind: 'queue', tweetId: r.tweetId };
    }
    if (r.reason === 'overlength' || r.reason === 'guard') {
      queue = queue.slice(1); // dropped + logged inside the choke point
      await xQueueSave(queue);
      continue;
    }
    if (r.reason === 'budget' || r.reason === 'killswitch') return { sent: 0, stopped: r.reason };
    // failed (after the choke point's one retry): strike the item; the
    // third failed tick drops it for good so a poisoned item can never
    // head-of-line block the queue forever.
    head.attempts = (head.attempts ?? 0) + 1;
    if (head.attempts >= 3) {
      await xLoopLog({ kind: 'queue', status: 'dropped_failed', detail: `queue:${head.id} attempts:${head.attempts}`, text: head.text });
      queue = queue.slice(1);
    }
    await xQueueSave(queue);
    return { sent: 0, failed: 'queue' };
  }
  return { sent: 0 };
}

// Single-item priority drain (outage notices, 2026-11-04): mirrors
// xLoopDrainQueue's rules for exactly ONE head item — sent → dequeue,
// overlength/guard → drop, budget/killswitch → stopped, failed → strike
// (dropped for good on the 3rd failed tick). It NEVER touches the item
// behind the head, so a priority tick can never leak a marketing send
// past the pacing gate: the marketing item waits for its own tick.
async function xLoopDrainPriorityHead(deps) {
  const queue = await xQueueList();
  const head = queue[0];
  if (!head || !head.priority) return { sent: 0 };
  // Video items can never ride the priority path (priority has no
  // videoJobId parameter by design): a corrupted/hand-crafted video
  // head drops here rather than ever posting text-only.
  if (head.videoJobId) {
    await xLoopLog({ kind: 'queue', status: 'dropped_novideo', detail: `queue:${head.id} priority_video`, text: head.text });
    await xQueueSave(queue.slice(1));
    return { sent: 0, dropped: 'novideo' };
  }
  const r = await xLoopTrySend({ kind: 'queue', text: head.text, imageKey: head.imageKey ?? null, detail: `queue:${head.id}` }, deps);
  if (r.sent) {
    await xQueueSave(queue.slice(1));
    return { sent: 1, kind: 'queue', tweetId: r.tweetId };
  }
  if (r.reason === 'overlength' || r.reason === 'guard') {
    await xQueueSave(queue.slice(1));
    return { sent: 0, dropped: r.reason };
  }
  if (r.reason === 'budget' || r.reason === 'killswitch') return { sent: 0, stopped: r.reason };
  head.attempts = (head.attempts ?? 0) + 1;
  if (head.attempts >= 3) {
    await xLoopLog({ kind: 'queue', status: 'dropped_failed', detail: `queue:${head.id} attempts:${head.attempts}`, text: head.text });
    await xQueueSave(queue.slice(1));
  } else {
    await xQueueSave(queue);
  }
  return { sent: 0, failed: 'queue' };
}

// ── (B) Milestones — pending list inside config key xloop_state ────────────

async function xLoopReadState() {
  const s = await xLoopReadJson('xloop_state', null);
  return s && typeof s === 'object' ? s : {};
}

async function xLoopSaveState(state) {
  await setConfig('xloop_state', JSON.stringify(state)).catch(() => {});
}

/**
 * Enqueue one milestone cross-post (called by lib/tick.js at the same
 * fire points that send the Telegram celebration cards). The text is
 * composed by the caller from the event's own data — nothing is
 * invented here. Over-length is dropped + logged (never truncated);
 * the same event key can never enqueue twice (ring kept in state,
 * survives the pending list draining).
 */
export async function enqueueXMilestone(kind, key, text, imageKey = null, opts = {}) {
  const clean = String(text ?? '').trim();
  if (!clean) return { queued: false, reason: 'empty' };
  const k = String(key ?? '').slice(0, 120);
  if (xCharLen(clean) > XLOOP_MAX_CHARS) {
    await xLoopLog({ kind: 'milestone', status: 'dropped_overlength', detail: `${kind}:${k}`, text: clean });
    return { queued: false, reason: 'overlength' };
  }
  // Purchase announcements are never imageless (purchase-announce
  // wave 2026-10-27): a purchase item without a resolvable card is
  // HELD at the door, not queued.
  if (kind === 'purchase' && !resolveXImage(imageKey)) {
    await xLoopLog({ kind: 'milestone', status: 'dropped_noimage', detail: `${kind}:${k}`, text: clean });
    return { queued: false, reason: 'noimage' };
  }
  const state = await xLoopReadState();
  const ring = Array.isArray(state.milestoneKeys) ? state.milestoneKeys : [];
  if (ring.includes(k)) {
    await xLoopLog({ kind: 'milestone', status: 'dropped_duplicate', detail: `${kind}:${k}`, text: clean });
    return { queued: false, reason: 'duplicate' };
  }
  const now = Date.now();
  let pending = (Array.isArray(state.milestones) ? state.milestones : [])
    .filter((m) => m && now - (m.at ?? 0) < XLOOP_MILESTONE_TTL_MS && m.key !== k);
  pending.push({ kind, key: k, text: clean, imageKey: imageKey ?? null, product: opts.product ?? null, label: opts.label ?? null, budgetExempt: opts.budgetExempt === true, at: now, attempts: 0 });
  pending.sort((a, b) =>
    ((XLOOP_MILESTONE_PRIORITY[a.kind] ?? 9) - (XLOOP_MILESTONE_PRIORITY[b.kind] ?? 9)) || ((a.at ?? 0) - (b.at ?? 0)));
  // Cap reconciliation (purchase-announce wave 2026-10-27, found by
  // harness): purchases batch into ONE roundup post per tick, so they
  // do not consume tick slots the way generic milestones do — the
  // shared 5-cap would silently drop the 6th purchase in a spike
  // while its Telegram post had already gone out (pair broken).
  // Purchases therefore get their own cap (20, mirroring the queue),
  // and the trim keeps generic and purchase groups separate. An
  // item evicted by either trim returns queued:false (overflow) so
  // the Telegram hook — which fires only on queued:true — never
  // posts for an X item that was dropped: the pair stays atomic.
  const generic = pending.filter((m) => m.kind !== 'purchase');
  const purchases = pending.filter((m) => m.kind === 'purchase');
  for (const evicted of generic.slice(XLOOP_MILESTONE_MAX)) {
    await xLoopLog({ kind: 'milestone', status: 'dropped_overflow', detail: `${evicted.kind}:${evicted.key}`, text: evicted.text });
  }
  for (const evicted of purchases.slice(XLOOP_PURCHASE_MAX)) {
    await xLoopLog({ kind: 'milestone', status: 'dropped_overflow', detail: `${evicted.kind}:${evicted.key}`, text: evicted.text });
  }
  pending = [...generic.slice(0, XLOOP_MILESTONE_MAX), ...purchases.slice(0, XLOOP_PURCHASE_MAX)];
  const survived = pending.some((m) => m.key === k);
  state.milestones = pending;
  // Only survivors join the key ring: an overflow-dropped purchase
  // was announced NOWHERE (Telegram fires only on queued:true), so a
  // later replay of the same grant gets a second chance instead of a
  // permanent silent loss. A queued item stays ring-recorded, so
  // replays of announced purchases still dedup.
  if (survived) state.milestoneKeys = [...ring, k].slice(-XLOOP_KEY_RING_MAX);
  await xLoopSaveState(state);
  if (!survived) return { queued: false, reason: 'overflow' };
  return { queued: true };
}

async function xLoopDrainMilestones(state, deps) {
  const now = deps.nowMs ?? Date.now();
  const all = (Array.isArray(state.milestones) ? state.milestones : [])
    .filter((m) => m && now - (m.at ?? 0) < XLOOP_MILESTONE_TTL_MS);
  // Purchase items drain in xLoopDrainPurchases (before the budget
  // gate); this drain never double-attempts them — they ride through
  // untouched and rejoin the list on every exit path.
  const purchases = all.filter((m) => m.kind === 'purchase');
  const rest = all.filter((m) => m.kind !== 'purchase');
  const save = async () => { state.milestones = [...rest, ...purchases]; await xLoopSaveState(state); };
  let guard = 0;
  while (rest.length && guard++ < XLOOP_MILESTONE_MAX + 2) {
    const head = rest[0];
    const r = await xLoopTrySend({ kind: 'milestone', text: head.text, detail: `${head.kind}:${head.key}` }, deps);
    if (r.sent) {
      rest.shift();
      await save();
      return { sent: 1, kind: 'milestone', tweetId: r.tweetId };
    }
    if (r.reason === 'overlength' || r.reason === 'guard') {
      rest.shift();
      await save();
      continue;
    }
    if (r.reason === 'budget' || r.reason === 'killswitch') {
      await save();
      return { sent: 0, stopped: r.reason };
    }
    head.attempts = (head.attempts ?? 0) + 1;
    if (head.attempts >= 2) {
      await xLoopLog({ kind: 'milestone', status: 'dropped_failed', detail: `${head.kind}:${head.key}`, text: head.text });
      rest.shift();
    }
    await save();
    return { sent: 0, failed: 'milestone' };
  }
  await save();
  return { sent: 0 };
}

// ── (B2) Purchase drain — EXTRA-budget, roundup on spikes ───────────────
// Runs before the budget gate in cycleXLoop. One send per tick, like
// every other drain; a purchase send still ends the tick's sending.
// Roundup: ≥2 pending purchases become ONE post — same product →
// that product's card, mixed → the generic roundup card (text makes
// no product/price claim). On failure each batched item strikes
// (drop at 2, like other milestones). TTL 48h, same as milestones.
async function xLoopDrainPurchases(state, deps) {
  const now = deps.nowMs ?? Date.now();
  const all = (Array.isArray(state.milestones) ? state.milestones : [])
    .filter((m) => m && now - (m.at ?? 0) < XLOOP_MILESTONE_TTL_MS);
  const purchases = all.filter((m) => m.kind === 'purchase');
  const rest = all.filter((m) => m.kind !== 'purchase');
  const save = async (kept) => { state.milestones = [...rest, ...kept]; await xLoopSaveState(state); };
  if (!purchases.length) return { sent: 0 };
  let text;
  let imageKey;
  if (purchases.length >= 2) {
    const products = [...new Set(purchases.map((p) => p.product).filter(Boolean))];
    const label = purchases[0].label;
    if (products.length === 1 && label) {
      text = `🎉 ${purchases.length} new ${label} purchases — welcome to the PoorBoyAI family! #PoorBoyAI #PBAI`;
      imageKey = purchases[0].imageKey;
    } else {
      text = '🎉 New members joined the PoorBoyAI family today! Welcome aboard. #PoorBoyAI #PBAI';
      imageKey = 'roundup';
    }
  } else {
    text = purchases[0].text;
    imageKey = purchases[0].imageKey;
  }
  const r = await xLoopTrySend({ kind: 'milestone', text, imageKey, budgetExempt: true, detail: `purchase:${purchases.length >= 2 ? 'roundup' : purchases[0].key}` }, deps);
  if (r.sent) {
    await save([]);
    return { sent: 1, kind: 'purchase', tweetId: r.tweetId };
  }
  if (r.reason === 'overlength' || r.reason === 'guard') {
    // Poisoned batch (should not happen — hook composes short, safe
    // text): drop it, logged in the choke point.
    await save([]);
    return { sent: 0 };
  }
  if (r.reason === 'killswitch' || r.reason === 'budget') {
    await save(purchases);
    return { sent: 0, stopped: r.reason };
  }
  const kept = [];
  for (const p of purchases) {
    p.attempts = (p.attempts ?? 0) + 1;
    if (p.attempts >= 2) {
      await xLoopLog({ kind: 'milestone', status: 'dropped_failed', detail: `purchase:${p.key}`, text: p.text });
    } else {
      kept.push(p);
    }
  }
  await save(kept);
  return { sent: 0, failed: 'purchase' };
}

// ── (C) Mention replies — mentions of @Poorboyai only ──────────────────────

// Tick-wallclock wave (2026-11-06): the mention leg composes its reply
// with a brain call (~8-20s through a degraded ladder) — if the tick is
// already over its wall-clock budget, the leg defers to the next tick
// instead of starting a slow brain call that could die holding the tick
// lock. The tick clock is visible here via the heartbeat: lib/tick.js
// writes `tick_cycle_current = xLoop@<elapsed ms>` just before this
// cycle starts, so elapsed-at-the-leg is the heartbeat ms plus this
// cycle's own elapsed time. Must match TICK_BUDGET_MS in lib/tick.js
// (a shared constant would need a new module — 100-module cap — so the
// value is duplicated here with this pointer; the harness asserts both
// are 20,000). The whole leg defers (poll + reply): the poll is cheap
// to redo, and not polling leaves the watermark untouched, so held
// mentions retry on a later tick. Fail-open: an unreadable, stale, or
// non-xLoop heartbeat means "not over budget" and the leg runs.
export const XLOOP_TICK_BUDGET_MS = 20_000;
async function xLoopTickElapsedMs(cycleStartMs, nowMs) {
  try {
    const raw = String(await getConfig('tick_cycle_current', '') ?? '');
    const at = raw.lastIndexOf('@');
    if (at <= 0) return null;
    if (raw.slice(0, at) !== 'xLoop') return null; // stale mark, not this cycle
    const hbMs = Number(raw.slice(at + 1));
    if (!Number.isFinite(hbMs)) return null;
    return hbMs + Math.max(0, (nowMs ?? Date.now()) - cycleStartMs);
  } catch { return null; }
}

// Conservative spam/bot shape: near-zero followers with mass following,
// or a brand-new zero-follower account already following 100+. Anything
// ambiguous is treated as a person (we reply); skips are logged.
function xLoopLooksSpammy(user) {
  const m = user?.public_metrics ?? {};
  const followers = Number(m.followers_count ?? 0);
  const following = Number(m.following_count ?? 0);
  if (followers <= 1 && following >= 500) return true;
  const created = Date.parse(user?.created_at ?? '');
  if (Number.isFinite(created) && Date.now() - created < 7 * 86400_000 && followers === 0 && following >= 100) return true;
  return false;
}

async function xLoopMentions(state, deps) {
  const now = deps.nowMs ?? Date.now();
  if (state.lastMentionPollAt && now - state.lastMentionPollAt < XLOOP_MENTION_POLL_MS) {
    return { sent: 0, poll: 'gated' };
  }
  if (!state.selfId) {
    const me = await verifyXPublisherCreds(deps).catch(() => null);
    if (!me?.ok || !me.id) return { sent: 0, poll: 'no_self_id' };
    state.selfId = String(me.id);
    state.selfUsername = me.username ?? null;
  }
  state.lastMentionPollAt = now;
  let data;
  try {
    // Query string built by hand — the isolate has no URL /
    // URLSearchParams globals (the raid-wave finding recorded in
    // lib/raids.js); digest.js builds its X queries the same way.
    const qs = [
      'max_results=10',
      'tweet.fields=' + encodeURIComponent('created_at,conversation_id,author_id,text'),
      'expansions=author_id',
      'user.fields=' + encodeURIComponent('username,name,public_metrics,created_at'),
      ...(state.sinceId ? ['since_id=' + encodeURIComponent(state.sinceId)] : []),
    ].join('&');
    data = await raidXGet(`/2/users/${state.selfId}/mentions?${qs}`, deps);
  } catch (e) {
    if (e?.status === 429) await xLoopArmBackoff();
    await xLoopSaveState(state);
    return { sent: 0, poll: 'error', error: String(e?.message ?? e).slice(0, 120) };
  }
  const tweets = Array.isArray(data?.data) ? data.data : [];
  const users = new Map((data?.includes?.users ?? []).map((u) => [String(u.id), u]));
  if (!tweets.length) { await xLoopSaveState(state); return { sent: 0, poll: 'empty' }; }
  // First-ever poll is a silent baseline (the ATH pattern): seed the
  // watermark, reply to nothing historical.
  if (!state.baselineDone) {
    state.sinceId = tweets.map((t) => String(t.id)).sort(cmpXId).pop();
    state.baselineDone = true;
    await xLoopSaveState(state);
    return { sent: 0, poll: 'baseline' };
  }
  const day = xLoopDayKey(now);
  if (state.replyDay !== day) { state.replyDay = day; state.repliedAuthors = []; }
  // Decide mentions strictly oldest-first. The watermark advances ONLY
  // past mentions that were actually decided (skipped or attempted) —
  // the batch stops at the first send attempt, and anything after it
  // stays above the watermark for the next poll. Nothing is silently
  // swallowed: every decided mention has a log row.
  const ordered = [...tweets].sort((a, b) => cmpXId(String(a.id), String(b.id)));
  for (const t of ordered) {
    const authorId = String(t.author_id ?? '');
    const user = users.get(authorId) ?? {};
    state.sinceId = String(t.id); // decided below, one way or another
    if (!authorId || authorId === state.selfId) {
      await xLoopLog({ kind: 'reply', status: 'skipped_self', inReplyTo: String(t.id), authorId: authorId || null });
      continue;
    }
    if ((state.repliedAuthors ?? []).includes(authorId)) {
      await xLoopLog({ kind: 'reply', status: 'skipped_repeat_author', inReplyTo: String(t.id), authorId });
      continue;
    }
    if (xLoopLooksSpammy(user)) {
      await xLoopLog({ kind: 'reply', status: 'dropped_spam', inReplyTo: String(t.id), authorId, detail: user.username ? `@${user.username}` : null });
      continue;
    }
    const body = String(t.text ?? '').replace(/@\w+/g, '').trim();
    if (body.length < 4) {
      await xLoopLog({ kind: 'reply', status: 'skipped_empty', inReplyTo: String(t.id), authorId });
      continue;
    }
    let draft = '';
    try {
      const ask = deps.ask ?? askLLM;
      draft = await ask({
        systemPrompt: XLOOP_REPLY_SYSTEM,
        userMessage: `@${user.username ?? 'someone'} on X said: "${String(t.text ?? '').slice(0, 500)}"\n\nWrite PB's reply.`,
        tier: 'chat',
        maxOutputTokens: 120,
      });
    } catch (e) {
      await xLoopLog({ kind: 'reply', status: 'failed', detail: 'compose: ' + String(e?.message ?? e).slice(0, 100), inReplyTo: String(t.id), authorId });
      continue;
    }
    draft = String(draft ?? '').replace(/\s*\n\s*/g, ' ').replace(/^["']+|["']+$/g, '').trim();
    if (!draft) {
      await xLoopLog({ kind: 'reply', status: 'failed', detail: 'compose_empty', inReplyTo: String(t.id), authorId });
      continue;
    }
    const r = await xLoopTrySend(
      { kind: 'reply', text: draft, replyTo: String(t.id), authorId, detail: user.username ? `@${user.username}` : null },
      deps,
    );
    if (r.sent) {
      state.repliedAuthors = [...(state.repliedAuthors ?? []), authorId];
      await xLoopSaveState(state);
      return { sent: 1, kind: 'reply', tweetId: r.tweetId };
    }
    await xLoopSaveState(state);
    if (r.reason === 'budget' || r.reason === 'killswitch') return { sent: 0, stopped: r.reason };
    // overlength / guard / failed — logged in the choke point. The
    // batch stops at the first send attempt either way: one attempt
    // per poll, and later mentions stay for the next poll.
    return { sent: 0, poll: 'done' };
  }
  await xLoopSaveState(state);
  return { sent: 0, poll: 'done' };
}

// ── The cycle (lib/tick.js 'xLoop') ─────────────────────────────────────────

export async function cycleXLoop(deps = {}) {
  const now = deps.nowMs ?? Date.now();
  if (await xLoopIsOff()) return { skipped: 'x_loop_off' };
  const backoffUntil = Number(await getConfig('raidtrack_backoff_until', '0')) || 0;
  if (now < backoffUntil) return { skipped: 'backoff', until: backoffUntil };
  const creds = await resolveXPublisherCreds(getConfig);
  if (!creds) return { skipped: 'no_x_creds' };
  const budget = await xLoopBudgetState(now);
  const out = { sent: 0, budget: { day: budget.day, posts: { used: budget.postsUsed, cap: budget.postsCap, remaining: budget.postsRemaining }, replies: { used: budget.repliesUsed, cap: budget.repliesCap, remaining: budget.repliesRemaining } } };
  const postsOpen = budget.postsRemaining > 0;
  const repliesOpen = budget.repliesRemaining > 0;
  const state = await xLoopReadState();

  // Video Phase B maintenance (video-to-X wave): a pending video
  // that never finishes processing drops after TTL — it can never
  // head-of-line block the loop forever. Runs on every non-off,
  // non-backoff tick, before any drain.
  let videoPending = await xVideoPendingRead();
  if (videoPending && now - (videoPending.firstSeenAt ?? 0) > X_VIDEO_PENDING_TTL_MS) {
    await xLoopLog({ kind: 'queue', status: 'video_timeout', detail: `video:${videoPending.queueId}`, text: videoPending.text });
    await xVideoPendingClear();
    videoPending = null;
  }

  // Purchase announcements drain FIRST, before the budget gate: they
  // are EXTRA-budget (Rowdy 2026-10-27). A purchase send still ends
  // the tick's sending, like any other send.
  const fromPurchases = await xLoopDrainPurchases(state, deps);
  if (fromPurchases.sent) { out.sent = 1; out.kind = 'purchase'; out.tweetId = fromPurchases.tweetId; return out; }
  if (fromPurchases.stopped) { out.stopped = fromPurchases.stopped; return out; }

  if (!postsOpen && !repliesOpen) { out.skipped = 'budget_spent'; return out; }

  // Outage notices (2026-11-04): a priority queue head bypasses the
  // pacing gap AND the LA window ("straight away" — an outage at 3am is
  // exactly when immediacy matters most). Everything above still
  // applies: kill switch, backoff, creds, budget gate. The send itself
  // still runs the choke point (char limit, guard, budget spend,
  // logging) via xLoopDrainPriorityHead, and a priority send still
  // stamps the pacing clock like any scheduled send. A priority tick
  // never sends marketing: any definitive priority outcome returns
  // here; only an empty-queue race falls through to the normal path.
  const queueHead = (await xQueueList())[0] ?? null;
  if (queueHead && queueHead.priority && postsOpen) {
    const fromPriority = await xLoopDrainPriorityHead(deps);
    if (fromPriority.sent) { await xLoopPacingStamp(now); out.sent = 1; out.kind = 'queue'; out.priority = true; out.tweetId = fromPriority.tweetId; return out; }
    if (fromPriority.stopped) { out.stopped = fromPriority.stopped; return out; }
    if (fromPriority.failed) { out.failed = fromPriority.failed; return out; }
    if (fromPriority.dropped) { out.dropped = fromPriority.dropped; return out; }
  }

  // Pacing gate (2026-10-28; mentions gated 2026-10-30 audit #9):
  // scheduled drains AND mention replies wait for the LA window and the
  // minimum gap. When blocked, everything below is skipped — a pacing
  // skip is never an error.
  let fromQueue = { sent: 0 };
  let fromMilestone = { sent: 0 };
  const pacing = await xLoopPacingCheck(now);
  if (!pacing.allowed) {
    out.skipped = pacing.reason;
  } else if (postsOpen) {
    // Video Phase B (video-to-X wave): poll the pending video's STATUS
    // on this tick. succeeded → post via the choke point with the
    // pre-uploaded mediaId (one send, pacing stamp, budget spend —
    // exactly like any other send). failed → drop + fall through.
    // still processing → log once, fall through (other items may use
    // this tick; the video retries next tick). A STATUS 429 arms
    // backoff and ends the tick without draining.
    if (videoPending) {
      let status;
      try {
        status = await xMediaStatus(videoPending.mediaId, creds, deps);
      } catch (e) {
        if (e?.status === 429) { await xLoopArmBackoff(); return out; }
        status = null; // transient STATUS error: leave pending, fall through
      }
      if (status) {
        const procState = status?.processing_info?.state;
        if (procState === 'succeeded' || !status?.processing_info) {
          const r = await xLoopTrySend({ kind: 'queue', text: videoPending.text, mediaIds: [videoPending.mediaId], detail: `video:${videoPending.queueId}` }, deps);
          if (r.sent) {
            await xVideoPendingClear();
            await xLoopPacingStamp(now);
            out.sent = 1; out.kind = 'queue'; out.video = true; out.tweetId = r.tweetId;
            return out;
          }
          if (r.reason === 'killswitch' || r.reason === 'budget') { out.stopped = r.reason; return out; }
          if (r.reason === 'overlength' || r.reason === 'guard') {
            await xVideoPendingClear();
            videoPending = null; // choke point already dropped + logged it; fall through to normal drains
          } else {
            videoPending.attempts = (videoPending.attempts ?? 0) + 1;
            if (videoPending.attempts >= 3) {
              await xLoopLog({ kind: 'queue', status: 'video_failed', detail: `video:${videoPending.queueId} attempts:${videoPending.attempts}`, text: videoPending.text });
              await xVideoPendingClear();
              videoPending = null;
            } else {
              await xVideoPendingWrite(videoPending);
            }
            return out; // a failed post attempt ends the tick; the video retries next tick
          }
        } else if (procState === 'failed') {
          await xLoopLog({ kind: 'queue', status: 'video_failed', detail: `video:${videoPending.queueId} ${String(status.processing_info.error?.message ?? 'processing failed').slice(0, 120)}`, text: videoPending.text });
          await xVideoPendingClear();
          videoPending = null; // fall through to normal drains
        } else if (!videoPending.processingLogged) {
          await xLoopLog({ kind: 'queue', status: 'video_processing', detail: `video:${videoPending.queueId}`, text: videoPending.text });
          videoPending.processingLogged = true;
          await xVideoPendingWrite(videoPending);
          // fall through: other items may use this tick while the video processes
        }
      }
    }
    fromQueue = await xLoopDrainQueue(deps);
    if (fromQueue.sent) { await xLoopPacingStamp(now); out.sent = 1; out.kind = 'queue'; out.tweetId = fromQueue.tweetId; return out; }
    if (fromQueue.stopped) { out.stopped = fromQueue.stopped; return out; }
    if (fromQueue.videoUploaded) { out.videoUploaded = true; return out; }

    fromMilestone = await xLoopDrainMilestones(state, deps);
    if (fromMilestone.sent) { await xLoopPacingStamp(now); out.sent = 1; out.kind = 'milestone'; out.tweetId = fromMilestone.tweetId; return out; }
    if (fromMilestone.stopped) { out.stopped = fromMilestone.stopped; return out; }
  }

  // Audit #9 (2026-10-30): a pacing-blocked mention reply is HELD, not
  // sent — the mention path does not run at all, so the watermark is
  // untouched, held mentions retry on a later tick, and a held reply
  // sends nothing and consumes no budget. Mention sends still never
  // stamp the clock (scheduled behavior unchanged).
  // Tick-wallclock wave (2026-11-06): same hold shape for an
  // over-budget tick — the leg defers instead of starting its brain
  // call (see xLoopTickElapsedMs above). A deferred reply sends
  // nothing, consumes no budget, and retries next tick.
  let fromMentions;
  if (!pacing.allowed) {
    fromMentions = { sent: 0, poll: 'held_pacing' };
  } else if (((await xLoopTickElapsedMs(now, deps.nowMs ?? Date.now())) ?? 0) > XLOOP_TICK_BUDGET_MS) {
    fromMentions = { sent: 0, poll: 'deferred_wallclock' };
  } else {
    fromMentions = await xLoopMentions(state, deps);
  }
  if (fromMentions.sent) { out.sent = 1; out.kind = 'reply'; out.tweetId = fromMentions.tweetId; return out; }
  if (fromMentions.stopped) out.stopped = fromMentions.stopped;
  if (fromMentions.poll) out.mentions = fromMentions.poll;
  if (fromMentions.error) out.mentionsError = fromMentions.error;
  if (fromQueue.failed || fromMilestone.failed || fromPurchases.failed) out.failed = fromQueue.failed ?? fromMilestone.failed ?? fromPurchases.failed;
  return out;
}

/** Owner-facing snapshot for /xqueue (status + recent audit rows). */
export async function xLoopStatus() {
  const off = await xLoopIsOff();
  const budget = await xLoopBudgetState(Date.now());
  const queue = await xQueueList();
  const state = await xLoopReadState();
  const recent = await db.select().from(x_loop_log)
    .orderBy(desc(x_loop_log.id)).limit(5).all().catch(() => []);
  return {
    off,
    budget,
    queue,
    pendingVideo: await xVideoPendingRead(),
    pendingMilestones: Array.isArray(state.milestones) ? state.milestones : [],
    recentLog: recent.map((r) => ({
      ts: r.ts, kind: r.kind, status: r.status, tweetId: r.tweetId ?? null,
      text: r.text ?? null, detail: r.detail ?? null,
    })),
  };
}

// Harness seam: the pure helpers, for the wave's stubbed-transport proofs.
// xLoopTrySend joins the seam for the X-split wave (2026-11-05): the choke
// point is the budget enforcement, so the harness must drive it directly.
export const __xloopTest = { xLoopDayKey, xLoopLooksSpammy, cmpXId, xCharLen, xOAuthHeader, xPostStatsScore, xPostStatsParseTweet, xPostStatsDisplayKind, xPostStatsBoardText, xPostStatsVideoViews, xPostStatsVideoQueueId, xLoopTrySend, xLoopBudgetState };

// ── X post analytics (2026-10-28) — collection + ranking + scoreboard ────
// Reads ONLY: one batch GET per 6h for PB's own sent tweets (all kinds;
// purchases log as kind 'milestone' with a 'purchase:' detail prefix — see
// PB-XPOST-ANALYTICS-SPEC-2026-10-28.md §1 correction). Never touches
// sends, pacing, budget, or cap. X failures skip + back off, never score,
// never page (read-only-feed precedent, like lpListings).

const XPOST_STATS_KEY = 'xpost_stats';
const XPOST_STATS_POLL_MS = 6 * 3600_000;
const XPOST_STATS_BACKOFF_MS = 15 * 60_000;
const XPOST_STATS_FREEZE_DAYS = 7;
const XPOST_STATS_RETENTION_DAYS = 30;
const XPOST_STATS_MAX = 120;
const XPOST_STATS_FIELDS = 'tweet.fields=public_metrics,created_at&expansions=attachments.media_keys&media.fields=public_metrics';
const XPOST_STATS_KINDS = new Set(['queue', 'milestone', 'reply']);
// Phase 2 per-place reach (2026-11-06): the X poll cannot see Telegram,
// so Telegram legs are recorded at SEND time into a pending key, keyed by
// the X queue item id (the log's `video:<queueId>` detail joins them to
// the tweet at poll time). The video-post flow (watch / temp endpoint)
// knows the queue id from the queue read-back, same as the 2026-11-06
// trailer/eagle post. No in-tree Telegram send path exists for video
// legs — they go out via that external flow — so this key is the seam.
const XPOST_PENDING_LEGS_KEY = 'xpost_pending_legs';
const XPOST_LEARN_FLAG = 'xpost_learn_on';
// Telegram leg chats (verified 2026-11-06, PB-VIDEO-POST record):
// ads channel -1003703317130, home group -1003956732308.
const XPOST_TG_ADS_CHAT_ID = '-1003703317130';
const XPOST_TG_HOME_CHAT_ID = '-1003956732308';
const XPOST_TG_CHAT_IDS = new Set([XPOST_TG_ADS_CHAT_ID, XPOST_TG_HOME_CHAT_ID]);

async function xPostStatsRead() {
  const raw = await xLoopReadJson(XPOST_STATS_KEY, null);
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return { updatedAt: 0, tweets: {} };
  const tweets = raw.tweets && typeof raw.tweets === 'object' && !Array.isArray(raw.tweets) ? raw.tweets : {};
  return { updatedAt: Number(raw.updatedAt) || 0, tweets };
}

async function xPostStatsWrite(stats, now, opts = {}) {
  const cutoffSec = Math.floor(now / 1000) - XPOST_STATS_RETENTION_DAYS * 86400;
  const entries = Object.entries(stats.tweets ?? {})
    .filter(([, r]) => r && Number.isFinite(Number(r.sentTs)) && Number(r.sentTs) >= cutoffSec);
  entries.sort((a, b) => Number(a[1].sentTs) - Number(b[1].sentTs));
  const tweets = {};
  for (const [id, r] of entries.slice(-XPOST_STATS_MAX)) tweets[id] = r;
  // touch:false (reply/view note writes) keeps the stored updatedAt, so
  // the board's "last poll" time still means the last X poll, not the
  // last Telegram reply counted.
  const updatedAt = opts.touch === false ? (Number(stats.updatedAt) || 0) : now;
  await setConfig(XPOST_STATS_KEY, JSON.stringify({ updatedAt, tweets })).catch(() => {});
  return tweets;
}

function xPostStatsDisplayKind(row) {
  return String(row?.detail ?? '').startsWith('purchase:') ? 'purchase' : String(row?.kind ?? '');
}

function xPostStatsScore(m) {
  const n = (v) => (Number.isFinite(Number(v)) ? Number(v) : 0);
  const engagement = n(m?.likes) + n(m?.reposts) + n(m?.replies) + n(m?.quotes);
  const reach = m?.reach == null ? null : n(m.reach);
  return { engagement, reach, rate: reach != null && reach > 0 ? engagement / reach : null };
}

function xPostStatsParseTweet(t) {
  const m = t?.public_metrics;
  if (!m || typeof m !== 'object') return null;
  const n = (v) => (Number.isFinite(Number(v)) ? Number(v) : 0);
  return {
    likes: n(m.like_count), reposts: n(m.retweet_count),
    replies: n(m.reply_count), quotes: n(m.quote_count),
    reach: m.impression_count == null ? null : n(m.impression_count),
  };
}

// Video views (2026-11-06): the poll's media expansion returns
// includes.media with public_metrics.view_count per attached media.
// First attached media with a numeric view_count wins (an X post carries
// at most one video in practice). null when no video attachment, when
// the attachment is a photo (no view_count), or when includes is absent
// — never 0-filled from absence.
function xPostStatsVideoViews(t, mediaByKey) {
  const keys = t?.attachments?.media_keys;
  if (!Array.isArray(keys) || !keys.length) return null;
  for (const k of keys) {
    const m = mediaByKey?.get(String(k));
    const v = m?.public_metrics?.view_count;
    if (Number.isFinite(Number(v))) return Number(v);
  }
  return null;
}

// Queue id out of a log row's detail: video posts log detail
// `video:<queueId>` (see cycleXLoop Phase B). Null for anything else.
function xPostStatsVideoQueueId(row) {
  const d = String(row?.detail ?? '');
  return d.startsWith('video:') ? d.slice('video:'.length) : null;
}

// ── Per-place reach: Telegram legs (2026-11-06) ────────────────────────────
// Telegram Bot API has NO getMessage-style method and NO documented
// `views` field on Message (docs crawled 2026-11-07 04:15 UTC), and the
// home group is a supergroup, where messages have no view counters at
// all — so Telegram reach is NEVER polled and NEVER scraped. What IS
// recorded, honestly:
//   - each leg at SEND time (chat, messageId, sentTs) via
//     xPostStatsRecordPendingLeg, keyed by X queue id; the poll joins it
//     to the tweet by the log's `video:<queueId>` detail;
//   - group replies to a tracked leg, counted from the message handler
//     (xPostStatsNoteReply), deduped by reply message id;
//   - channel views ONLY if an update ever carries a `views` field on a
//     tracked ads-channel leg (xPostStatsNoteChannelViews), stamped
//     "last seen <time>", never presented as a poll.
// Reactions have no handler slot (100-module cap blocks a
// message_reaction handler) — places.*.reactions stays null (unknown),
// never a fake 0. A leg's views/replies are only ever overwritten by a
// newer observation, never zeroed.

export async function xPostStatsRecordPendingLeg(queueId, place, leg) {
  if (!queueId || (place !== 'tgAds' && place !== 'tgHome')) return { ok: false, reason: 'bad_args' };
  const chat = String(leg?.chat ?? '');
  const messageId = Number(leg?.messageId);
  if (!chat || !Number.isFinite(messageId)) return { ok: false, reason: 'bad_leg' };
  const all = (await xLoopReadJson(XPOST_PENDING_LEGS_KEY, {})) ?? {};
  const cur = (all[String(queueId)] && typeof all[String(queueId)] === 'object' ? all[String(queueId)] : {});
  // recordedAt bounds the key: a video that never posts (dropped queue
  // item) leaves a dead entry, and a future prune can drop it by age.
  // Legs attach on the next poll; attached entries are deleted there.
  cur.recordedAt = Date.now();
  cur[place] = {
    chat, messageId,
    sentTs: Number.isFinite(Number(leg?.sentTs)) ? Number(leg.sentTs) : null,
    views: null, viewsAt: null, replies: 0, replyIds: [],
  };
  all[String(queueId)] = cur;
  await setConfig(XPOST_PENDING_LEGS_KEY, JSON.stringify(all)).catch(() => {});
  return { ok: true };
}

function xPostStatsFindLeg(stats, chat, messageId) {
  for (const [id, r] of Object.entries(stats.tweets ?? {})) {
    const places = r?.places ?? {};
    for (const place of ['tgAds', 'tgHome']) {
      const leg = places[place];
      if (leg && String(leg.chat) === String(chat) && Number(leg.messageId) === Number(messageId)) {
        return { id, place, leg };
      }
    }
  }
  return null;
}

export async function xPostStatsNoteReply(message, now = Date.now()) {
  const chat = String(message?.chat?.id ?? '');
  if (!XPOST_TG_CHAT_IDS.has(chat)) return { noted: false, reason: 'chat' };
  const replyTo = Number(message?.reply_to_message?.message_id);
  if (!Number.isFinite(replyTo)) return { noted: false, reason: 'no_reply' };
  const stats = await xPostStatsRead();
  const hit = xPostStatsFindLeg(stats, chat, replyTo);
  if (!hit) return { noted: false, reason: 'no_leg' };
  const mid = Number(message?.message_id);
  const ids = Array.isArray(hit.leg.replyIds) ? hit.leg.replyIds : [];
  if (Number.isFinite(mid) && ids.includes(mid)) return { noted: false, reason: 'dup' };
  if (Number.isFinite(mid)) {
    ids.push(mid);
    if (ids.length > 200) ids.splice(0, ids.length - 200);
  }
  hit.leg.replies = (Number(hit.leg.replies) || 0) + 1;
  hit.leg.replyIds = ids;
  await xPostStatsWrite(stats, now, { touch: false });
  return { noted: true, tweetId: hit.id, place: hit.place };
}

export async function xPostStatsNoteChannelViews(message, now = Date.now()) {
  const v = message?.views;
  if (!Number.isFinite(Number(v))) return { noted: false, reason: 'no_views' };
  const chat = String(message?.chat?.id ?? '');
  if (chat !== XPOST_TG_ADS_CHAT_ID) return { noted: false, reason: 'chat' };
  const mid = Number(message?.message_id);
  if (!Number.isFinite(mid)) return { noted: false, reason: 'no_id' };
  const stats = await xPostStatsRead();
  const hit = xPostStatsFindLeg(stats, chat, mid);
  if (!hit || hit.place !== 'tgAds') return { noted: false, reason: 'no_leg' };
  hit.leg.views = Number(v);
  hit.leg.viewsAt = now;
  await xPostStatsWrite(stats, now, { touch: false });
  return { noted: true, tweetId: hit.id };
}

export async function cycleXPostStats(deps = {}) {
  const now = deps.nowMs ?? Date.now();
  if (await xLoopIsOff()) return { skipped: 'x_loop_off' };
  const sharedBackoff = Number(await getConfig('raidtrack_backoff_until', '0')) || 0;
  const ownBackoff = Number(await getConfig('xpoststats_backoff_until', '0')) || 0;
  if (now < sharedBackoff || now < ownBackoff) return { skipped: 'backoff' };
  const lastPoll = Number(await getConfig('xpoststats_last_poll_at', '0')) || 0;
  if (now - lastPoll < XPOST_STATS_POLL_MS) return { skipped: 'not_due' };
  const dbx = deps.db ?? db;
  const rows = await dbx.select().from(x_loop_log)
    .orderBy(desc(x_loop_log.id)).limit(150).all().catch(() => []);
  const freezeSec = Math.floor(now / 1000) - XPOST_STATS_FREEZE_DAYS * 86400;
  const eligible = rows.filter((r) => r && r.status === 'sent' && r.tweetId
    && XPOST_STATS_KINDS.has(r.kind) && Number(r.ts) >= freezeSec);
  if (!eligible.length) {
    await setConfig('xpoststats_last_poll_at', String(now)).catch(() => {});
    return { polled: 0, eligible: 0 };
  }
  const ids = [...new Set(eligible.map((r) => String(r.tweetId)))].slice(0, 100);
  let data;
  try {
    data = await raidXGet(`/2/tweets?ids=${ids.join(',')}&${XPOST_STATS_FIELDS}`, deps);
  } catch (e) {
    await setConfig('xpoststats_backoff_until', String(now + XPOST_STATS_BACKOFF_MS)).catch(() => {});
    return { skipped: 'x_error', status: e?.status ?? null };
  }
  // Empty-data guard (live lesson 2026-10-28: a poll that wrote empty stats
  // with eligible tweets present must never eat the 6h window): an empty
  // data array with no errors entry is a failed read, not a zero score.
  // Back off without writing or stamping. Errors present means genuinely
  // unavailable tweets — proceed so gone-marking still runs.
  if (eligible.length > 0 && !(data?.data ?? []).length && !(data?.errors ?? []).length) {
    await setConfig('xpoststats_backoff_until', String(now + XPOST_STATS_BACKOFF_MS)).catch(() => {});
    return { skipped: 'x_empty' };
  }
  const stats = await xPostStatsRead();
  const byId = new Map(eligible.map((r) => [String(r.tweetId), r]));
  const mediaByKey = new Map((data?.includes?.media ?? [])
    .map((m) => [String(m?.media_key ?? ''), m]));
  const pendingLegs = (await xLoopReadJson(XPOST_PENDING_LEGS_KEY, {})) ?? {};
  let pendingChanged = false;
  const seen = new Set();
  let scored = 0;
  let legsAttached = 0;
  for (const t of data?.data ?? []) {
    const id = String(t?.id ?? '');
    if (!id || !byId.has(id)) continue;
    const m = xPostStatsParseTweet(t);
    if (!m) continue;
    const row = byId.get(id);
    const sc = xPostStatsScore(m);
    // A null from an absent media block is not a newer observation:
    // keep the last-known view count for a video tweet that already
    // had one (frozen tweets keep last-known values by design). A
    // real observed 0 still overwrites; text/photo posts stay null
    // (their previous value is also null).
    const prevVideoViews = stats.tweets[id]?.videoViews;
    const freshViews = xPostStatsVideoViews(t, mediaByKey);
    const videoViews = freshViews ?? (Number.isFinite(prevVideoViews) ? prevVideoViews : null);
    // Places survive a re-poll: the X leg refreshes, Telegram legs
    // (recorded at send time, replies/views counted since) are kept.
    const prevPlaces = stats.tweets[id]?.places;
    const places = (prevPlaces && typeof prevPlaces === 'object' ? { ...prevPlaces } : {});
    places.x = { reach: m.reach, videoViews, engagement: sc.engagement };
    // Pending-leg join: a video post's Telegram legs attach here, once.
    // A place already present keeps its leg WITH its counted replies —
    // the pending copy is the same leg recorded at send time, and
    // overwriting it would zero counters counted since (regression
    // caught by harness-xpost-stats 'poll-legs-preserve-replies').
    const qid = xPostStatsVideoQueueId(row);
    if (qid && pendingLegs[qid] && typeof pendingLegs[qid] === 'object') {
      let attachedAny = false;
      for (const place of ['tgAds', 'tgHome']) {
        if (pendingLegs[qid][place] && !places[place]) {
          places[place] = pendingLegs[qid][place];
          attachedAny = true;
        }
      }
      delete pendingLegs[qid];
      pendingChanged = true;
      if (attachedAny) legsAttached++;
    }
    stats.tweets[id] = {
      kind: xPostStatsDisplayKind(row),
      sentTs: Number(row.ts),
      text: String(row.text ?? '').replace(/\s*\n\s*/g, ' ').slice(0, 100),
      ...m, videoViews, engagement: sc.engagement, rate: sc.rate,
      lastPollAt: now, gone: false, places,
    };
    seen.add(id);
    scored++;
  }
  let gone = 0;
  const errIds = new Set();
  for (const e of data?.errors ?? []) {
    const v = e?.['resource-id'] ?? e?.value ?? '';
    if (v) errIds.add(String(v));
  }
  for (const id of ids) {
    if (!seen.has(id) && errIds.has(id) && stats.tweets[id]) {
      stats.tweets[id].gone = true;
      gone++;
    }
  }
  await xPostStatsWrite(stats, now);
  if (pendingChanged) {
    await setConfig(XPOST_PENDING_LEGS_KEY, JSON.stringify(pendingLegs)).catch(() => {});
  }
  await setConfig('xpoststats_last_poll_at', String(now)).catch(() => {});
  return { polled: ids.length, scored, gone, legsAttached, truncated: eligible.length > ids.length };
}

export async function xPostStatsBoard(now = Date.now(), deps = {}) {
  const stats = await xPostStatsRead();
  const dbx = deps.db ?? db;
  const rows = await dbx.select().from(x_loop_log)
    .orderBy(desc(x_loop_log.id)).limit(150).all().catch(() => []);
  const freezeSec = Math.floor(now / 1000) - XPOST_STATS_FREEZE_DAYS * 86400;
  const eligible = rows.filter((r) => r && r.status === 'sent' && r.tweetId
    && XPOST_STATS_KINDS.has(r.kind) && Number(r.ts) >= freezeSec);
  const scoredIds = new Set(Object.keys(stats.tweets));
  const unscored = eligible.filter((r) => !scoredIds.has(String(r.tweetId))).length;
  const list = Object.entries(stats.tweets).map(([id, r]) => ({ id, ...r }));
  const totals = {};
  for (const r of list) {
    const t = totals[r.kind] ?? (totals[r.kind] = { count: 0, engagement: 0, reach: 0 });
    t.count++;
    t.engagement += Number(r.engagement) || 0;
    t.reach += Number(r.reach) || 0;
  }
  const byRank = (a, b) => (b.engagement - a.engagement)
    || ((b.reach ?? -1) - (a.reach ?? -1)) || (b.sentTs - a.sentTs);
  const top = [...list].sort(byRank).slice(0, 5);
  const flops = list.filter((r) => now - Number(r.sentTs) * 1000 > 86400_000)
    .sort((a, b) => (a.engagement - b.engagement) || (a.sentTs - b.sentTs)).slice(0, 3);
  // Per-place reach rankings (2026-11-06): top by X reach, top by video
  // views, top Telegram where anything is known (ads views seen + home
  // replies; reactions are always unknown — no handler slot — so they
  // never rank). Telegram activity of 0 with no leg recorded is not a
  // ranking: the list stays empty and the board says so.
  const tgActivity = (r) => (Number(r?.places?.tgAds?.views) || 0)
    + (Number(r?.places?.tgAds?.replies) || 0)
    + (Number(r?.places?.tgHome?.replies) || 0);
  const topReach = [...list].sort((a, b) => ((b.reach ?? -1) - (a.reach ?? -1)) || (b.sentTs - a.sentTs)).slice(0, 3);
  const topVideo = list.filter((r) => r.videoViews != null)
    .sort((a, b) => (Number(b.videoViews) - Number(a.videoViews)) || (b.sentTs - a.sentTs)).slice(0, 3);
  const topTelegram = list.filter((r) => tgActivity(r) > 0)
    .sort((a, b) => (tgActivity(b) - tgActivity(a)) || (b.sentTs - a.sentTs)).slice(0, 3);
  const learnOn = flagValueOn(await getConfig(XPOST_LEARN_FLAG, '0').catch(() => '0'));
  const learnBlock = xPostLearnBlockText({ tweets: stats.tweets }, now);
  return { updatedAt: stats.updatedAt, totals, top, flops, scored: list.length, unscored, topReach, topVideo, topTelegram, learnOn, learnBlock };
}

export function xPostStatsBoardText(board) {
  const fmtTime = (ms) => {
    if (!ms) return 'never';
    try { return new Date(ms).toISOString().replace('T', ' ').slice(0, 16) + ' UTC'; } catch { return 'never'; }
  };
  const fmtReach = (r) => (r == null ? '?' : String(r));
  const fmtRate = (r) => (r == null ? '' : ` · ${(r * 100).toFixed(1)}%`);
  const fmtViews = (r) => (r?.videoViews == null ? '' : ` · 🎬 ${r.videoViews} views`);
  const lines = [`📊 X post stats · last poll ${fmtTime(board.updatedAt)} · ${board.scored} scored, ${board.unscored} unscored`, ''];
  for (const [kind, t] of Object.entries(board.totals)) {
    lines.push(`${kind}: ${t.count} posts · ${t.engagement} eng · ${t.reach} reach`);
  }
  lines.push('', 'TOP:');
  if (!board.top.length) lines.push('(none yet)');
  for (const r of board.top) {
    lines.push(`${r.engagement} eng · ${fmtReach(r.reach)} reach${fmtRate(r.rate)}${fmtViews(r)} · [${r.kind}]${r.gone ? ' (gone)' : ''} ${r.text}`);
  }
  lines.push('', 'FLOPS (sent >24h ago):');
  if (!board.flops.length) lines.push('(none yet)');
  for (const r of board.flops) {
    lines.push(`${r.engagement} eng · ${fmtReach(r.reach)} reach${fmtRate(r.rate)}${fmtViews(r)} · [${r.kind}]${r.gone ? ' (gone)' : ''} ${r.text}`);
  }
  // Per-place reach (2026-11-06): one line per listed post. X reach is
  // the poll's impression_count; video views ride the same poll. Ads
  // views are "not seen yet" until an update carries them (Telegram has
  // no views poll — see the note in lib/repurpose.js). Home is a
  // supergroup: views are n/a there by platform design, replies count.
  const seenPlace = new Set();
  const placed = [...(board.top ?? []), ...(board.flops ?? [])]
    .filter((r) => { if (seenPlace.has(r.id)) return false; seenPlace.add(r.id); return true; });
  lines.push('', 'REACH BY PLACE:');
  if (!placed.length) lines.push('(none yet)');
  for (const r of placed) {
    const ads = r?.places?.tgAds;
    const home = r?.places?.tgHome;
    const adsPart = !ads ? 'ads: no leg recorded'
      : `ads: ${ads.views == null ? 'views not seen yet' : `${ads.views} views${ads.viewsAt ? ` (last seen ${fmtTime(ads.viewsAt)})` : ''}`} · ${ads.replies || 0} replies`;
    const homePart = !home ? 'home: no leg recorded'
      : `home: views n/a (groups don’t report views) · ${home.replies || 0} replies`;
    lines.push(`[${r.kind}] ${r.text} — X: ${fmtReach(r.reach)} reach${r.videoViews == null ? '' : `, ${r.videoViews} views`} · ${adsPart} · ${homePart}`);
  }
  // LEARNED (spec §9): the winners block the loop feeds to drafting,
  // shown here so the influence is visible. When learning is OFF the
  // block is shown anyway, marked as not fed.
  lines.push('', `LEARNED (learning ${board.learnOn ? 'ON — winners feed new drafts' : 'OFF — winners shown, not fed to drafting'} · ${board.scored} scored, bar 30):`);
  const topReach = board.topReach?.[0];
  const topVideo = board.topVideo?.[0];
  const topTg = board.topTelegram?.[0];
  lines.push(topReach ? `Top X reach: [${topReach.kind}] ${topReach.text} — ${topReach.reach ?? '?'} reach` : 'Top X reach: (none yet)');
  lines.push(topVideo ? `Top video: [${topVideo.kind}] ${topVideo.text} — ${topVideo.videoViews} views` : 'Top video: (none yet)');
  // Unknown ads views render as unknown, never as an observed 0 —
  // the REACH BY PLACE line above says "views not seen yet" for the
  // same state, and this line must not contradict it. (Home replies
  // keep `?? 0`: replies are a counted integer, initialized to 0.)
  const topAdsViews = topTg?.places?.tgAds?.views;
  lines.push(topTg ? `Top Telegram: [${topTg.kind}] ${topTg.text} — ${topAdsViews == null ? 'ads views not seen yet' : `${topAdsViews} ads views`} · ${topTg.places?.tgHome?.replies ?? 0} home replies` : 'Top Telegram: (nothing recorded yet)');
  lines.push(board.learnBlock ? board.learnBlock : '(no winners in the last 30 days)');
  return lines.join('\n');
}
